def safe_key(text):

    return (

        str(text)

        .replace(" ", "_")

        .replace("/", "_")

        .replace("+", "_")

        .replace("-", "_")
    )


@st.cache_resource
def load_model(model_path):

    return joblib.load(model_path)


def get_fai_class(fai_value):

    if fai_value >= 70:

        return "Good"

    elif fai_value >= 55:

        return "Moderate"

    elif fai_value >= 40:

        return "Poor"

    else:

        return "Critical"



