def get_template_bytes(template_name):
    encoded = ASSESSMENT_TEMPLATE_B64.get(template_name)
    if encoded is None:
        raise KeyError(f"Unknown template: {template_name}")
    return base64.b64decode(encoded)


def _excel_text(value):
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except Exception:
        pass
    return str(value).strip()


def _excel_number(value, field_name):
    numeric_value = pd.to_numeric(value, errors="coerce")
    if pd.isna(numeric_value):
        raise ValueError(f"{field_name} must contain a numeric value.")
    return float(numeric_value)


UPLOAD_ASSESSMENT_PROTOCOL = "B01_COUNT_OR_RECORD_WEIGHTS_V2"


def _upload_optional_number(value):
    """Missing results stay missing; booleans and non-finite values are not indices."""
    if value is None or isinstance(value, (bool, np.bool_)):
        return None
    number = pd.to_numeric(value, errors="coerce")
    if pd.isna(number) or not np.isfinite(number):
        return None
    return float(number)


def _format_upload_value(value, missing="Pending"):
    number = _upload_optional_number(value)
    return f"{number:.2f}" if number is not None else missing


def _upload_ai_ready(result):
    """Only a fresh, numerically complete import may populate Excel-mode AI inputs."""
    if (not result
            or result.get("template_type") != "Complete Building Assessment"
            or result.get("Import_Protocol") != UPLOAD_ASSESSMENT_PROTOCOL):
        return False
    names = ["DI", "PLI", "SI", "FAI"]
    flag = result.get("TRI_Availability_Flag")
    if flag not in (0, 1):
        return False
    if flag == 1:
        names.append("TRI")
    values = [_upload_optional_number(result.get(name)) for name in names]
    return all(value is not None and 0.0 <= value <= 100.0 for value in values)


def _clear_upload_ai_fields():
    for key in (
        "ai_building_id", "ai_building_name", "ai_building_function",
        "ai_structural_system", "ai_building_age", "ai_number_of_floors",
        "ai_di", "ai_pli", "ai_tri", "ai_tri_status", "ai_si",
        "ai_cf1", "ai_cf2", "ai_cf3", "ai_excel_function_unmapped",
    ):
        st.session_state.pop(key, None)
    st.session_state["ai_excel_pending_sync"] = False
    st.session_state["ai_excel_input_selected"] = False


def _clear_upload_derived_results():
    """Invalidate results tied to the previous upload before loading new inputs."""
    _clear_upload_ai_fields()
    for key in (
        "calculated_fai", "latest_calculated_fai", "latest_predicted_fai",
        "latest_final_assessment_building_index", "latest_assessment_summary",
        "latest_result_source", "latest_final_decision", "latest_fai_scenario",
    ):
        st.session_state[key] = None
    for key in (
        "calculated_fai_class", "latest_calculated_fai_class",
        "latest_predicted_class", "latest_building_condition",
    ):
        st.session_state[key] = "Not Available"
    st.session_state["fai_calculation_results"] = pd.DataFrame()
    st.session_state["latest_confirmed_critical_failures"] = []
    st.session_state.pop("uploaded_complete_assessment", None)


def _attach_upload_element_counts(
    excel_file, elements, sheet_name, *, allow_workbook_record_weights=True
):
    """Prefer explicit counts; otherwise accept a complete declared record-weight basis."""
    data = elements.copy()
    context = _upload_import_context(excel_file)
    missing_markers = {"", "not available", "not provided", "not documented", "pending", "n/a", "na", "unknown"}

    # Preserve supplied record weights before the count-aware calculation resets G.
    raw_record_weights = (
        data["Applied_Element_Weight"].copy()
        if "Applied_Element_Weight" in data.columns
        else pd.Series(np.nan, index=data.index)
    )
    data["Workbook_Applied_Element_Weight"] = raw_record_weights
    numeric_record_weights = pd.to_numeric(raw_record_weights, errors="coerce")
    record_weight_is_bool = raw_record_weights.map(
        lambda value: isinstance(value, (bool, np.bool_))
    )

    def validated_counts(values, label):
        missing = values.apply(_excel_text).str.lower().isin(missing_markers)
        numeric = pd.to_numeric(values.where(~missing), errors="coerce")
        boolean_values = values.map(lambda value: isinstance(value, (bool, np.bool_)))
        invalid = ~missing & (
            numeric.isna() | ~np.isfinite(numeric) | (numeric <= 0)
            | ~np.isclose(numeric, np.round(numeric), rtol=0.0, atol=1e-9)
            | boolean_values
        )
        if invalid.any():
            raise ValueError(
                f"{label} must be a positive whole number when supplied. Review Element_ID: "
                + ", ".join(data.loc[invalid, "Element_ID"].tolist())
            )
        return numeric.astype(float)

    # These are per-record count fields. Category totals and stock quantities
    # are deliberately not aliases for element counts.
    count_fields = [
        name for name in (
            "Element_Count", "Represented_Units",
            "Original_Verified_Column_Count", "Original_Column_Count",
        ) if name in data.columns
    ]
    if count_fields:
        raw_counts = pd.Series(np.nan, index=data.index, dtype=float)
        count_sources = pd.Series("", index=data.index, dtype=object)
        for field in count_fields:
            values = validated_counts(data[field], field)
            provided = values.notna()
            if field in {"Original_Verified_Column_Count", "Original_Column_Count"}:
                wrong_category = provided & data["Element_Type"].ne("Column")
                if wrong_category.any():
                    raise ValueError(
                        f"{field} is a Column count field. Review Element_ID: "
                        + ", ".join(data.loc[wrong_category, "Element_ID"].tolist())
                    )
            overlap = raw_counts.notna() & provided
            conflict = overlap & ~np.isclose(
                raw_counts, values, rtol=0.0, atol=1e-9, equal_nan=True
            )
            if conflict.any():
                raise ValueError(
                    "Conflicting explicit count fields for Element_ID: "
                    + ", ".join(data.loc[conflict, "Element_ID"].tolist())
                )
            take = raw_counts.isna() & provided
            raw_counts.loc[take] = values.loc[take]
            if "Count_Source" in data.columns:
                references = data["Count_Source"].apply(_excel_text)
            elif field == "Element_Count":
                references = pd.Series("", index=data.index)
            else:
                # A header containing 'Verified' is retained as a source
                # locator only; it does not confer independent verification.
                references = pd.Series(f"{sheet_name}.{field}", index=data.index)
            count_sources.loc[take] = references.loc[take]
        context["sources"]["DI element counts"] = "; ".join(
            f"{sheet_name}.{name}" for name in count_fields
        )
    else:
        records = {}
        source_label = "Not provided; no one-element-per-row assumption"
        if sheet_name == "Element_Inventory" and "Calculation_Details" in excel_file.sheet_names:
            grid = _upload_sheet_grid(excel_file, "Calculation_Details")
            required = {"Element_ID", "Element_Type", "Element_Count", "Count_Source"}
            headings = []
            for row_number in range(len(grid)):
                row = [_excel_text(value) for value in grid.iloc[row_number]]
                if required.issubset(set(row)):
                    headings.append((row_number, row))
            if len(headings) > 1:
                raise ValueError("Calculation_Details contains ambiguous element-count tables.")
            if headings:
                header_row, headings_row = headings[0]
                positions = {name: headings_row.index(name) for name in required}
                source_label = f"Calculation_Details count inputs (header row {header_row + 1}; matched by Element_ID)"
                inventory_types = data.set_index("Element_ID")["Element_Type"].to_dict()
                for row_number in range(header_row + 1, len(grid)):
                    values = {name: grid.iat[row_number, column] for name, column in positions.items()}
                    if all(_excel_text(value) == "" for value in values.values()):
                        break
                    element_id = _excel_text(values["Element_ID"])
                    if not element_id:
                        raise ValueError(f"Calculation_Details count row {row_number + 1} lacks Element_ID.")
                    if element_id not in inventory_types:
                        raise ValueError(f"Calculation_Details count table references unknown Element_ID {element_id}.")
                    if element_id in records:
                        raise ValueError(f"Calculation_Details count table duplicates Element_ID {element_id}.")
                    if _excel_text(values["Element_Type"]) != inventory_types[element_id]:
                        raise ValueError(f"Calculation_Details count category disagrees with inventory for {element_id}.")
                    records[element_id] = values
        raw_counts = data["Element_ID"].map(
            {key: record["Element_Count"] for key, record in records.items()}
        )
        count_sources = data["Element_ID"].map(
            {key: _excel_text(record["Count_Source"]) for key, record in records.items()}
        ).fillna("")
        context["sources"]["DI element counts"] = source_label


    numeric = validated_counts(raw_counts, "Element_Count")
    data["Element_Count"] = numeric
    data["Count_Source"] = count_sources
    source_known = ~count_sources.str.lower().isin(
        missing_markers | {"unsupported", "unverified", "not independently verified"}
    )
    data["Count_Provided"] = numeric.notna()
    data["Count_Source_Provided"] = numeric.notna() & source_known
    data["Count_Status"] = np.where(
        data["Count_Source_Provided"], "User Provided - source recorded",
        np.where(numeric.notna(), "User Provided - source pending", "Pending - count"),
    )
    missing_source_ids = data.loc[numeric.notna() & ~source_known, "Element_ID"].tolist()
    if missing_source_ids:
        context["warnings"].append(
            "Source evidence is pending for explicitly supplied element counts: "
            + ", ".join(missing_source_ids)
            + ". These counts are used as user-provided inputs; they have not been independently verified."
        )
    data["Group_Rows_in_Category"] = data.groupby("Element_Type")["Element_ID"].transform("size")
    data["Elements_in_Category"] = np.nan
    data["Applied_Element_Weight"] = np.nan
    data["Declared_Record_Weights_Used"] = False
    data["DI_Weight_Basis"] = "Pending - element counts"
    for category, group in data.groupby("Element_Type"):
        if group["Count_Provided"].all():
            total = float(group["Element_Count"].sum())
            if not np.isfinite(total) or total <= 0:
                raise ValueError("The supplied category element-count total must be finite and positive.")
            data.loc[group.index, "Elements_in_Category"] = total
            data.loc[group.index, "Applied_Element_Weight"] = (
                group["Category_AHP_Weight"] * group["Element_Count"] / total
            )
            data.loc[group.index, "DI_Weight_Basis"] = "Explicit element counts"
        elif group["Count_Provided"].any():
            # Never mix partial physical counts with a record-weight fallback.
            continue
        elif allow_workbook_record_weights:
            supplied = numeric_record_weights.loc[group.index]
            valid = (
                supplied.notna() & np.isfinite(supplied) & (supplied > 0)
                & ~record_weight_is_bool.loc[group.index]
            )
            category_weight = float(group["Category_AHP_Weight"].iloc[0])
            valid_total = valid.all() and np.isclose(
                float(supplied.sum()), category_weight, rtol=0.0, atol=1e-8
            )
            if valid_total:
                # Normalize only the accepted rounding residual, preserving
                # the supplied within-category proportions and raw values.
                data.loc[group.index, "Applied_Element_Weight"] = (
                    supplied * category_weight / float(supplied.sum())
                )
                data.loc[group.index, "Declared_Record_Weights_Used"] = True
                data.loc[group.index, "DI_Weight_Basis"] = "Workbook assessment-record weights"
                data.loc[group.index, "Count_Status"] = "Not supplied - record weights used"
                context["sources"][f"DI record weights ({category})"] = (
                    f"{sheet_name}.Applied_Element_Weight; validated declared record weights"
                )
                # Counts and their category totals remain unknown (NaN).
            else:
                context["warnings"].append(
                    f"DI record weights were not accepted for {category}: all must be finite, "
                    "positive numeric values and sum to the category AHP weight within 1e-8. "
                    "No element counts are imputed."
                )
    return data


def _explicit_sound_observation(row):
    """Only an explicit sound/no-damage condition can replace an absent damage record."""
    accepted_columns = {
        "condition", "element_condition", "observed_condition", "source_condition",
        "original_condition", "condition_status", "damage_status", "inspection_condition",
    }
    accepted_values = {
        "sound", "undamaged", "no damage", "not damaged", "no observed damage",
        "no visible damage", "intact", "سليم", "سليمة", "لا يوجد ضرر", "لا توجد أضرار",
    }
    for column, value in row.items():
        if str(column).strip().lower().replace(" ", "_") in accepted_columns:
            normalized = " ".join(_excel_text(value).lower().replace("_", " ").replace("-", " ").split())
            if normalized in accepted_values:
                return True
    return False


def _upload_source_qualifications(excel_file):
    """Keep declared source-review qualifications separate from calculation checks."""
    messages = []
    if "PLI_Audit" in excel_file.sheet_names:
        grid = _upload_sheet_grid(excel_file, "PLI_Audit")
        for _, row in grid.iterrows():
            if len(row) < 2:
                continue
            topic = _excel_text(row.iloc[0])
            note = _excel_text(row.iloc[1])
            if topic in {"AHP reciprocity", "SI provenance"} and note:
                messages.append(f"Source review - {topic}: {note}")
    return messages


def _declared_zero_assessment_basis(row):
    """Recognize explicit zero declarations, preserving their evidence basis."""
    if _explicit_sound_observation(row):
        return "Explicit sound observation"

    element_id = _excel_text(row.get("Element_ID"))
    if not element_id:
        return ""
    source_list = _excel_text(row.get("Source_Element_List"))
    source_note = " ".join(_excel_text(row.get("Source_Audit_Note")).split())
    count = _upload_optional_number(row.get("Element_Count"))
    if count is not None and count > 0 and float(count).is_integer() and source_list:
        members = [member.strip() for member in source_list.split(",") if member.strip()]
        expected_prefix = (
            f"Traceability grouping of {int(count)} source-listed elements "
            "with no retained damage record."
        )
        declared_clauses = [
            clause.strip().lower()
            for sentence in source_note.split(".")
            for clause in sentence.split(";")
        ]
        if (
            len(members) == int(count) and len(set(members)) == len(members)
            and source_note.lower().startswith(expected_prefix.lower())
            and "no damage is assigned to this row" in declared_clauses
        ):
            return "Declared zero assessment - source-listed group"

    confirmation = " ".join(_excel_text(row.get("PLI_No_Damage_Confirmation")).lower().split())
    confirmation_source = " ".join(_excel_text(row.get("Condition_Confirmation_Source")).split())
    source_parts = confirmation_source.split(":", 1)
    if (
        confirmation == "undamaged" and len(source_parts) == 2
        and source_parts[0].lower().startswith("user confirmation in this conversation")
        and source_parts[1].strip().rstrip(".").lower() == f"{element_id} is undamaged".lower()
    ):
        return "User-provided whole-element no-damage confirmation"
    return ""


def _aggregate_b01_uploaded_di(elements, element_di_map):
    elements = elements.copy()
    elements["Element_DI"] = elements["Element_ID"].map(element_di_map)
    elements["Damage_Record_Status"] = "Recorded damage"
    unobserved = elements["Element_DI"].isna()
    zero_basis = elements.apply(_declared_zero_assessment_basis, axis=1)
    declared_zero = zero_basis.ne("") & unobserved
    elements.loc[declared_zero, "Element_DI"] = 0.0
    elements.loc[declared_zero, "Damage_Record_Status"] = zero_basis.loc[declared_zero]
    elements.loc[unobserved & ~declared_zero, "Damage_Record_Status"] = "Pending - no damage observation"
    category_rows = []
    pending_reasons = []
    elements["Weighted_DI"] = np.nan
    elements["Category_DI"] = np.nan
    elements["DI_Count_Method"] = ""
    for category, group in elements.groupby("Element_Type", sort=False):
        weight = float(group["Category_AHP_Weight"].iloc[0])
        grade = None
        if group["Element_DI"].isna().any():
            missing_ids = group.loc[group["Element_DI"].isna(), "Element_ID"].tolist()
            method = "Pending - damage observation"
            pending_reasons.append(
                "DI Pending: no damage observation or explicit sound condition for "
                + ", ".join(missing_ids) + ". Missing records are not scored as zero."
            )
        elif group["Count_Provided"].all():
            counts = group["Element_Count"].astype(float)
            grade = float((counts * group["Element_DI"]).sum() / counts.sum())
            method = "Explicitly provided element counts"
            elements.loc[group.index, "Weighted_DI"] = (
                group["Applied_Element_Weight"] * group["Element_DI"]
            )
        elif group["Declared_Record_Weights_Used"].all():
            record_weights = group["Applied_Element_Weight"].astype(float)
            grade = float(
                (record_weights * group["Element_DI"]).sum() / record_weights.sum()
            )
            method = "Workbook assessment-record weights"
            elements.loc[group.index, "Weighted_DI"] = (
                record_weights * group["Element_DI"]
            )
        elif len(group) == 1:
            grade = float(group["Element_DI"].iloc[0])
            method = "Algebraic cancellation - one group"
            # This category's count cancels; the unknown count stays NaN.
            elements.loc[group.index, "Applied_Element_Weight"] = weight
            elements.loc[group.index, "Weighted_DI"] = weight * grade
        elif np.allclose(
            group["Element_DI"].to_numpy(dtype=float),
            float(group["Element_DI"].iloc[0]), rtol=0.0, atol=1e-10,
        ):
            grade = float(group["Element_DI"].iloc[0])
            method = "Algebraic cancellation - identical grades"
            # Individual count shares remain unknown; do not split W equally.
        else:
            method = "Pending - actual element counts"
            missing_ids = group.loc[~group["Count_Provided"], "Element_ID"].tolist()
            pending_reasons.append(
                f"DI Pending: {category} has unequal group grades and lacks explicit element counts for "
                + ", ".join(missing_ids) + ". No one-element-per-row assumption is applied."
            )
        elements.loc[group.index, "DI_Count_Method"] = method
        if grade is not None:
            elements.loc[group.index, "Category_DI"] = grade
        category_rows.append({
            "Element_Type": category, "Category_AHP_Weight": weight,
            "Category_DI": grade, "Count_Method": method,
            "Weighted_Category_DI": weight * grade if grade is not None else None,
        })
    denominator = sum(row["Category_AHP_Weight"] for row in category_rows)
    if denominator <= 0:
        raise ValueError("The applicable DI category-weight sum is zero.")
    di_value = (
        None if pending_reasons
        else float(sum(row["Weighted_Category_DI"] for row in category_rows) / denominator)
    )
    elements.attrs["pending_reasons"] = pending_reasons
    elements.attrs["category_results"] = category_rows
    return di_value, elements


def _read_building_info(excel_file):
    if "Building_Info" not in excel_file.sheet_names:
        raise ValueError("The workbook does not contain a Building_Info sheet.")

    raw = pd.read_excel(
        excel_file,
        sheet_name="Building_Info",
        header=None,
    )

    info = {}
    for _, row in raw.iterrows():
        if len(row) < 2:
            continue
        key = _excel_text(row.iloc[0])
        if key == "":
            continue
        info[key] = row.iloc[1]

    return info


def _normalize_structural_system(value):
    system = _excel_text(value)
    aliases = {
        "Reinforced Concrete (RC)": "RC",
        "Traditional / Heritage Masonry": "Traditional/Heritage Masonry",
        "Traditional Heritage Masonry": "Traditional/Heritage Masonry",
    }
    system = aliases.get(system, system)

    if system not in AHP_ELEMENT_WEIGHTS:
        raise ValueError(
            "Structural_System is missing or is not one of the approved structural systems."
        )

    return system


def _read_table(excel_file, sheet_name):
    if sheet_name not in excel_file.sheet_names:
        raise ValueError(f"The workbook does not contain the required sheet: {sheet_name}.")

    table = pd.read_excel(
        excel_file,
        sheet_name=sheet_name,
        header=2,
    )
    table.columns = [str(column).strip() for column in table.columns]
    return table


def _read_upload_ahp_weights(excel_file, system):
    """Read canonical or schema-qualified legacy element weights."""
    system = _normalize_structural_system(system)
    required = ["Structural_System", "Element_Type", "Category_AHP_Weight"]
    sheet_name = None
    table = None
    if "AHP_Element_Weights" in excel_file.sheet_names:
        sheet_name = "AHP_Element_Weights"
        table = _read_table(excel_file, sheet_name).copy()
    elif "AHP_Weights" in excel_file.sheet_names:
        candidate = _read_table(excel_file, "AHP_Weights").copy()
        if set(required).issubset(candidate.columns):
            sheet_name = "AHP_Weights"
            table = candidate
        elif set(required).intersection(candidate.columns):
            missing = [column for column in required if column not in candidate.columns]
            raise ValueError(
                "AHP_Weights contains an incomplete element-weight table; missing columns: "
                + ", ".join(missing)
            )
        # SI's AHP_Weights table has a different schema and is not an element source.

    if table is None:
        return (
            AHP_ELEMENT_WEIGHTS[system]["weights"].copy(),
            "Application defaults (AHP_Element_Weights sheet absent)",
            [],
        )

    missing = [column for column in required if column not in table.columns]
    if missing:
        raise ValueError(
            f"{sheet_name} is missing required columns: " + ", ".join(missing)
        )
    aliases = {
        "Reinforced Concrete (RC)": "RC",
        "Traditional / Heritage Masonry": "Traditional/Heritage Masonry",
        "Traditional Heritage Masonry": "Traditional/Heritage Masonry",
    }
    source_systems = table["Structural_System"].apply(_excel_text).replace(aliases)
    selected = table.loc[source_systems == system].copy()
    if selected.empty:
        raise ValueError(
            f"{sheet_name} contains no category weights for {system}."
        )
    selected["Element_Type"] = selected["Element_Type"].apply(_excel_text)
    if (selected["Element_Type"] == "").any():
        raise ValueError(
            f"{sheet_name} contains an empty Element_Type for {system}."
        )
    duplicated = selected.loc[
        selected["Element_Type"].duplicated(keep=False), "Element_Type"
    ].tolist()
    if duplicated:
        raise ValueError(
            f"{sheet_name} contains duplicate categories for {system}: "
            + ", ".join(sorted(set(duplicated)))
        )
    values = pd.to_numeric(selected["Category_AHP_Weight"], errors="coerce")
    boolean_values = selected["Category_AHP_Weight"].map(
        lambda value: isinstance(value, (bool, np.bool_))
    )
    invalid = values.isna() | ~np.isfinite(values) | (values <= 0) | boolean_values
    if invalid.any():
        raise ValueError(
            f"{sheet_name} requires a finite positive numeric weight for: "
            + ", ".join(selected.loc[invalid, "Element_Type"].tolist())
        )
    weights = dict(zip(selected["Element_Type"], values.astype(float)))
    warnings = []
    defaults = AHP_ELEMENT_WEIGHTS[system]["weights"]
    if set(weights) != set(defaults) or any(
        not np.isclose(value, defaults.get(category, np.nan), rtol=0.0, atol=1e-12)
        for category, value in weights.items()
    ):
        warnings.append(
            f"The workbook supplies its own AHP category weights for {system}; "
            "these values are used consistently for DI, PLI, and TRI."
        )
    weight_sum = float(sum(weights.values()))
    if not np.isfinite(weight_sum):
        raise ValueError(f"{sheet_name} category weight total must be finite.")
    if not np.isclose(weight_sum, 1.0, rtol=0.0, atol=1e-3):
        warnings.append(
            f"The supplied {system} AHP category weights total {weight_sum:.12g}. "
            "Index calculations normalize the weights of the applicable categories."
        )
    return weights, f"Workbook {sheet_name} ({system})", warnings


def _compare_saved_excel(excel_file, info, result):
    """Compare cached export values for review without using them as inputs."""
    columns = ["Index", "Saved Excel", "Recomputed B01", "Difference", "Status"]
    comparison = pd.DataFrame(columns=columns)
    comparison.attrs["saved_sources"] = {}
    comparison.attrs["warnings"] = []
    if "App_Export" not in excel_file.sheet_names:
        return comparison

    # Preserve supplied export layouts: B07 uses row 2 and DI_raw/PLI_raw.
    export_grid = _upload_sheet_grid(excel_file, "App_Export")
    header_rows = []
    index_headers = {"DI", "DI_raw", "PLI", "PLI_raw", "PLI_Raw_Loss", "TRI", "SI", "FAI"}
    for row_number in range(min(10, len(export_grid))):
        labels = [_excel_text(value) for value in export_grid.iloc[row_number]]
        if "Building_ID" in labels and len(index_headers.intersection(labels)) >= 2:
            header_rows.append(row_number)
    if len(header_rows) > 1:
        comparison.attrs["warnings"].append(
            "App_Export contains ambiguous header rows; saved values cannot be compared."
        )
        return comparison
    if header_rows:
        export = pd.read_excel(excel_file, sheet_name="App_Export", header=header_rows[0])
        export.columns = [str(column).strip() for column in export.columns]
    else:
        export = _read_table(excel_file, "App_Export")
    building_id = _excel_text(info.get("Building_ID"))
    saved_row = None
    if building_id and "Building_ID" in export.columns:
        matches = export.loc[export["Building_ID"].apply(_excel_text) == building_id]
        if len(matches) == 1:
            saved_row = matches.iloc[0]
        else:
            comparison.attrs["warnings"].append(
                f"App_Export has {len(matches)} rows matching Building_ID {building_id}; "
                "saved values cannot be compared unambiguously."
            )
    elif len(export) > 0:
        # Templates without an identifier store their one export row at row 4.
        saved_row = export.iloc[0]

    def finite_number(value):
        if isinstance(value, (bool, np.bool_)):
            return None
        numeric = pd.to_numeric(value, errors="coerce")
        if pd.isna(numeric) or not np.isfinite(numeric):
            return None
        return float(numeric)

    rows = []
    saved_sources = comparison.attrs["saved_sources"]
    for index_name in ["DI", "PLI", "TRI", "SI", "FAI"]:
        if index_name not in result:
            continue
        source_column = index_name
        convert_benefit = False
        if index_name == "DI":
            source_column = next((name for name in ["DI", "DI_raw"] if name in export.columns), None)
        elif index_name == "PLI":
            raw_columns = ["PLI_Raw_Loss", "PLI", "PLI_raw"]
            benefit_columns = ["PLI_Benefit_Score", "PLI_Benefit"]
            source_column = next((name for name in raw_columns if name in export.columns), None)
            if source_column is None:
                source_column = next(
                    (name for name in benefit_columns if name in export.columns), None
                )
                convert_benefit = source_column is not None
        source_exists = saved_row is not None and source_column in export.columns
        saved = saved_row[source_column] if source_exists else None
        saved_numeric = finite_number(saved)
        if convert_benefit and saved_numeric is not None:
            saved_numeric = 100.0 - saved_numeric
        if source_column is not None:
            if index_name == "PLI":
                saved_sources[index_name] = (
                    f"100 - App_Export.{source_column} (converted to raw loss)"
                    if convert_benefit else f"App_Export.{source_column} (raw loss)"
                )
            else:
                saved_sources[index_name] = f"App_Export.{source_column}"

        recalculated = finite_number(result.get(index_name))
        if index_name == "TRI" and result.get("TRI_Availability_Flag") == 0:
            recalculated = None
        difference = None
        if index_name in result.get("Pending_Indices", []) and recalculated is None:
            status = "Pending"
            if saved_numeric is not None:
                status = "Stale saved value"
                comparison.attrs["warnings"].append(
                    f"Saved Excel {index_name} is numeric while the current B01 calculation is Pending. "
                    "That saved value is not used as an input or sent to AI."
                )
        elif not source_exists or _excel_text(saved) == "":
            status = "Missing saved value"
        elif saved_numeric is None or recalculated is None:
            status = "Unavailable" if saved_numeric is None and recalculated is None else "Different"
        else:
            difference = recalculated - saved_numeric
            status = "Match" if abs(difference) <= 1e-8 else "Different"
        rows.append({
            "Index": index_name,
            "Saved Excel": saved_numeric if saved_numeric is not None else _excel_text(saved),
            "Recomputed B01": recalculated if recalculated is not None else "Not Available",
            "Difference": difference,
            "Status": status,
        })

    output = pd.DataFrame(rows, columns=columns)
    output.attrs = comparison.attrs
    return output


def _upload_import_context(excel_file):
    context = getattr(excel_file, "_assessment_import_context", None)
    if context is None:
        context = {"sources": {}, "warnings": [], "infos": [], "grids": {}, "formula_grids": {}}
        excel_file._assessment_import_context = context
    return context


def _upload_sheet_grid(excel_file, sheet_name, formulas=False):
    context = _upload_import_context(excel_file)
    cache = context["formula_grids" if formulas else "grids"]
    if sheet_name not in cache:
        if formulas:
            original = excel_file.io
            if hasattr(original, "getvalue"):
                source_bytes = original.getvalue()
            else:
                source_bytes = Path(original).read_bytes()
            with pd.ExcelFile(
                BytesIO(source_bytes), engine="openpyxl", engine_kwargs={"data_only": False}
            ) as formula_file:
                cache[sheet_name] = pd.read_excel(
                    formula_file, sheet_name=sheet_name, header=None, dtype=object
                )
        else:
            cache[sheet_name] = pd.read_excel(
                excel_file, sheet_name=sheet_name, header=None, dtype=object
            )
    return cache[sheet_name]


def _upload_ahp_weights(excel_file, system):
    weights, source, messages = _read_upload_ahp_weights(excel_file, system)
    context = _upload_import_context(excel_file)
    context["sources"]["AHP category weights"] = source
    for message in messages:
        target = "infos" if message.startswith("The workbook supplies its own AHP category weights") else "warnings"
        if message not in context[target]:
            context[target].append(message)
    return weights


def _read_active_pli_inputs(excel_file, elements):
    """Select the referenced input table and recompute from its raw fields."""
    import re
    from openpyxl.utils.cell import column_index_from_string, get_column_letter

    context = _upload_import_context(excel_file)
    raw = _upload_sheet_grid(excel_file, "Physical_Loss")
    formulas = _upload_sheet_grid(excel_file, "Physical_Loss", formulas=True)
    if len(raw) < 3:
        raise ValueError("Physical_Loss has no row-3 input headers.")
    headers = [_excel_text(value) for value in raw.iloc[2]]
    record_headers = {"Loss_Record_ID", "Damage_Record_ID", "Damage_ID", "Source_Damage_ID"}
    output_headers = {
        "Physical_Loss_Quantity", "Physical_Loss_Quantity (group units)",
        "Record_Loss_Qty", "Record_Loss_Quantity", "Capped_Loss_Once",
        "Element_Loss_Qty_Capped_Once", "Element_Loss_Capped_Once",
    }
    aliases = {
        "element": ["Element_ID"],
        "extent": ["Damage_Extent_%", "Extent_%"],
        "severity": ["Severity_Factor", "Severity"],
        "quantity": ["Verified_Total_Quantity", "Total_Quantity"],
        "unit": ["Measurement_Basis", "Unit"],
    }
    starts = [index for index, name in enumerate(headers) if name in record_headers]
    candidates = []
    for number, start in enumerate(starts):
        end = starts[number + 1] if number + 1 < len(starts) else len(headers)
        mapping = {"record": start}
        for field, names in aliases.items():
            matches = [index for index in range(start, end) if headers[index] in names]
            if len(matches) == 1:
                mapping[field] = matches[0]
        outputs = [index for index in range(start, end) if headers[index] in output_headers]
        if all(field in mapping for field in aliases) and outputs:
            candidates.append({"mapping": mapping, "outputs": outputs, "start": start, "end": end})
    if not candidates:
        raise ValueError("Physical_Loss has no supported complete raw-input table.")

    inventory = elements.set_index("Element_ID", drop=False)
    inventory_ids = set(inventory.index)
    calculation_rows = {}
    referenced_outputs = set()
    loss_headings = {
        "Element_Loss_Quantity", "Element_Capped_Loss_Qty", "Capped_Element_Loss",
        "Capped_Loss", "Capped_Loss_Quantity", "Element_Loss_Qty",
    }
    external_reference = re.compile(
        r"(?:'([^']+)'|([A-Za-z_][A-Za-z0-9_]*))!\$?([A-Z]+)\$?(\d+)(?::\$?([A-Z]+)\$?(\d+))?",
        re.IGNORECASE,
    )

    def cell(grid, row, column):
        return grid.iat[row, column] if row < len(grid) and column < len(grid.columns) else None

    if "Calculation_Details" in excel_file.sheet_names:
        calculation = _upload_sheet_grid(excel_file, "Calculation_Details")
        calculation_formulas = _upload_sheet_grid(excel_file, "Calculation_Details", formulas=True)
        blocks = []
        for row_number in range(len(calculation_formulas)):
            row_headers = [_excel_text(value) for value in calculation_formulas.iloc[row_number]]
            new_blocks = []
            for quantity_col, heading in enumerate(row_headers):
                if heading not in {"Total_Quantity", "Verified_Total_Quantity"}:
                    continue
                ids = [i for i in range(quantity_col) if row_headers[i] == "Element_ID"]
                loss_cols = [i for i in range(quantity_col + 1, len(row_headers)) if row_headers[i] in loss_headings]
                if ids and loss_cols:
                    new_blocks.append((ids[-1], quantity_col, loss_cols[0]))
            if new_blocks:
                blocks = new_blocks
                continue
            for id_col, quantity_col, loss_col in blocks:
                element_id = _excel_text(cell(calculation, row_number, id_col))
                if element_id not in inventory_ids:
                    continue
                formula = _excel_text(cell(calculation_formulas, row_number, loss_col))
                if not formula.startswith("=") or not re.search(r"SUMIFS?\s*\(", formula, re.IGNORECASE):
                    continue
                refs = [
                    column_index_from_string(match.group(3)) - 1
                    for match in external_reference.finditer(formula)
                    if (match.group(1) or match.group(2)).lower() == "physical_loss"
                ]
                used = {column for column in refs if column < len(headers) and headers[column] in output_headers}
                if not used:
                    continue
                if element_id in calculation_rows:
                    raise ValueError(f"Calculation_Details has ambiguous PLI rows for {element_id}.")
                calculation_rows[element_id] = (row_number, quantity_col, formula)
                referenced_outputs.update(used)
    selected = [table for table in candidates if referenced_outputs.intersection(table["outputs"])]
    if not selected and len(candidates) == 1 and not referenced_outputs:
        selected = candidates
    if len(selected) != 1:
        raise ValueError(
            "Physical_Loss contains multiple or ambiguous input tables. "
            "Calculation_Details must identify exactly one active PLI loss table."
        )
    table = selected[0]
    mapping = table["mapping"]
    source_label = (
        "Physical_Loss!" + get_column_letter(table["start"] + 1) + ":"
        + get_column_letter(max(table["outputs"]) + 1)
    )
    context["sources"]["PLI records"] = source_label + (
        " (selected by Calculation_Details formula dependencies)" if referenced_outputs
        else " (single supported input table)"
    )
    helper_table = headers[mapping["record"]] != "Loss_Record_ID"
    damage_rows = {}
    damage_grid = None
    damage_id_col = None
    if helper_table:
        damage_grid = _upload_sheet_grid(excel_file, "Damage_Assessment")
        damage_headers = [_excel_text(value) for value in damage_grid.iloc[2]]
        damage_id_col = next((i for i, name in enumerate(damage_headers) if name in record_headers), 0)
        for row_number in range(3, len(damage_grid)):
            record_id = _excel_text(cell(damage_grid, row_number, damage_id_col))
            if not record_id:
                continue
            if record_id in damage_rows:
                raise ValueError(f"Damage_Assessment has duplicate damage record ID {record_id}.")
            damage_rows[record_id] = {
                name: cell(damage_grid, row_number, index)
                for index, name in enumerate(damage_headers) if name
            }

    inventory_quantity_col = None
    inventory_grid = _upload_sheet_grid(excel_file, "Element_Inventory")
    inventory_headers = [_excel_text(value) for value in inventory_grid.iloc[2]]
    inventory_id_col = inventory_headers.index("Element_ID")
    if "Total_Quantity" in inventory_headers:
        inventory_quantity_col = inventory_headers.index("Total_Quantity")
    record_quantities = {}

    def quantity_value(sheet_name, row, column, element_id, seen=None):
        seen = set() if seen is None else set(seen)
        address = (sheet_name, row, column)
        if address in seen:
            raise ValueError("Circular PLI quantity dependency at " + str(address))
        seen.add(address)
        formula_grid = _upload_sheet_grid(excel_file, sheet_name, formulas=True)
        value = cell(formula_grid, row, column)
        label = f"{sheet_name}!{get_column_letter(column + 1)}{row + 1}"
        if sheet_name == "Element_Inventory" and column == inventory_quantity_col:
            referenced_id = _excel_text(cell(inventory_grid, row, inventory_id_col))
            if referenced_id != element_id:
                raise ValueError(f"{label} refers to a different Element_ID ({referenced_id}), not {element_id}.")
        if isinstance(value, (int, float, np.number)) and not isinstance(value, (bool, np.bool_)):
            numeric = float(value)
        elif isinstance(value, str) and value.startswith("="):
            direct = re.fullmatch(
                r"=\s*(?:(?:'([^']+)'|([A-Za-z_][A-Za-z0-9_]*))!)?\$?([A-Z]+)\$?(\d+)\s*",
                value, flags=re.IGNORECASE,
            )
            if direct:
                return quantity_value(
                    direct.group(1) or direct.group(2) or sheet_name,
                    int(direct.group(4)) - 1,
                    column_index_from_string(direct.group(3)) - 1,
                    element_id, seen,
                )
            expression = re.sub(r'"(?:[^"]|"")*"', '""', value)
            function_names = set(re.findall(r"\b([A-Z_][A-Z0-9_.]*)\s*\(", expression, re.IGNORECASE))
            allowed_functions = {"IF", "IFERROR", "INDEX", "MATCH", "COUNTIF", "COUNTIFS", "ISNUMBER", "AND", "OR", "NOT"}
            if (re.search(r"[+*/^&-]", expression)
                    or not function_names
                    or {name.upper() for name in function_names} - allowed_functions):
                raise ValueError(f"Unsupported arithmetic or quantity formula at {label}; only explicit references and guarded passthroughs are supported.")
            references = list(external_reference.finditer(value))
            inventory_refs = [match for match in references if (match.group(1) or match.group(2)).lower() == "element_inventory"]
            if inventory_refs and any(
                (match.group(1) or match.group(2)).lower() != "element_inventory"
                for match in references
            ):
                raise ValueError(f"Mixed active quantity sources at {label} are not supported.")
            for reference in inventory_refs:
                if reference.group(5) is None:
                    referenced_id = _excel_text(cell(inventory_grid, int(reference.group(4)) - 1, inventory_id_col))
                    if referenced_id != element_id:
                        raise ValueError(f"{label} refers to another inventory element ({referenced_id}), not {element_id}.")
            if inventory_quantity_col is not None and any(
                column_index_from_string(match.group(3)) - 1 == inventory_quantity_col
                for match in inventory_refs
            ):
                # Respect explicit source evidence guards without promoting a header to evidence.
                allowed_statuses = [status for status in ("Verified", "User Provided") if f'"{status}"' in value]
                if allowed_statuses:
                    referenced_columns = {column_index_from_string(match.group(3)) - 1 for match in inventory_refs}
                    status_columns = [
                        inventory_headers[index] for index in referenced_columns
                        if index < len(inventory_headers) and "support_status" in inventory_headers[index].lower()
                    ]
                    for status_column in status_columns:
                        if _excel_text(inventory.loc[element_id].get(status_column)) not in allowed_statuses:
                            raise ValueError(f"{label} does not permit the source quantity status for {element_id}.")
                numeric = pd.to_numeric(inventory.loc[element_id].get("Total_Quantity"), errors="coerce")
            else:
                helper_refs = [match for match in references if (match.group(1) or match.group(2)).lower() == "physical_loss"
                               and column_index_from_string(match.group(3)) - 1 == mapping["quantity"]]
                if helper_refs and element_id in record_quantities:
                    numeric = record_quantities[element_id]
                else:
                    raise ValueError(f"Unsupported or ambiguous active PLI quantity dependency at {label}.")
        else:
            raise ValueError(f"{label} has no numeric active PLI quantity for {element_id}.")
        if pd.isna(numeric) or not np.isfinite(numeric) or numeric <= 0:
            raise ValueError(f"{label} must provide a finite positive quantity for {element_id}.")
        return float(numeric)

    records = []
    seen_records = set()
    resolved_record_ids = {}
    for row_number in range(3, max(len(raw), len(formulas))):
        record_id = _excel_text(cell(raw, row_number, mapping["record"]))
        id_formula = _excel_text(cell(formulas, row_number, mapping["record"]))
        if helper_table and "Damage_Assessment!" in id_formula:
            linked_rows = {int(match.group(4)) - 1 for match in external_reference.finditer(id_formula)
                           if (match.group(1) or match.group(2)).lower() == "damage_assessment" and not match.group(5)}
            if len(linked_rows) == 1:
                record_id = _excel_text(cell(damage_grid, linked_rows.pop(), damage_id_col))
        resolved_record_ids[row_number] = record_id
    last_record_row = max((row for row, record_id in resolved_record_ids.items() if record_id), default=-1)
    for row_number, record_id in resolved_record_ids.items():
        values = {field: cell(raw, row_number, column) for field, column in mapping.items()}
        if not record_id and not _excel_text(values["element"]) and not _excel_text(values["severity"]):
            if row_number <= last_record_row and _excel_text(values["extent"]):
                raise ValueError(
                    f"{source_label} has an incomplete extent-only record at row {row_number + 1}; "
                    "record ID, element ID, and severity are required within the input records."
                )
            # A lone extent below the last input record can be an audit footer.
            continue
        if not record_id or record_id == "Not Available" or record_id in seen_records:
            raise ValueError(f"{source_label} contains a missing or duplicate record ID at row {row_number + 1}.")
        seen_records.add(record_id)
        if helper_table:
            if record_id not in damage_rows:
                raise ValueError(f"{source_label} references unknown damage record {record_id}.")
            source = damage_rows[record_id]
            for field, names in {
                "element": ["Element_ID"], "extent": ["Damage_Extent_%", "Extent_%"],
                "severity": ["Severity_Factor", "Severity"],
            }.items():
                field_formula = _excel_text(cell(formulas, row_number, mapping[field]))
                if "Damage_Assessment!" in field_formula:
                    source_name = next((name for name in names if name in source), None)
                    if source_name is None:
                        raise ValueError(f"Damage_Assessment lacks the raw {field} field for {record_id}.")
                    values[field] = source[source_name]
        element_id = _excel_text(values["element"])
        if element_id not in inventory_ids:
            raise ValueError(f"{source_label} references unknown Element_ID {element_id}.")
        quantity = quantity_value("Physical_Loss", row_number, mapping["quantity"], element_id)
        if element_id in record_quantities and not np.isclose(record_quantities[element_id], quantity, rtol=0.0, atol=1e-9):
            raise ValueError(f"{source_label} has inconsistent record quantities for {element_id}.")
        record_quantities[element_id] = quantity
        unit = _excel_text(values["unit"])
        inventory_unit = _excel_text(inventory.loc[element_id].get("Measurement_Basis"))
        if unit and inventory_unit and unit != inventory_unit:
            raise ValueError(f"{source_label} and Element_Inventory use different units for {element_id}.")
        records.append({
            "Loss_Record_ID": record_id, "Element_ID": element_id,
            "Damage_Extent_%": values["extent"], "Severity_Factor": values["severity"],
            "Record_Total_Quantity": quantity, "Measurement_Basis": unit or inventory_unit,
            "Source_Row": row_number + 1, "Input_Table": source_label,
        })

    adjusted = elements.copy()
    if "Total_Quantity" not in adjusted:
        adjusted["Total_Quantity"] = np.nan
    adjusted["Inventory_Total_Quantity"] = adjusted["Total_Quantity"]
    active_quantities = []
    quantity_sources = []
    for _, element in adjusted.iterrows():
        element_id = element["Element_ID"]
        if calculation_rows:
            if element_id not in calculation_rows:
                raise ValueError(f"Calculation_Details has no unambiguous active PLI quantity for {element_id}.")
            row_number, quantity_col, _ = calculation_rows[element_id]
            quantity = quantity_value("Calculation_Details", row_number, quantity_col, element_id)
            quantity_source = f"Calculation_Details!{get_column_letter(quantity_col + 1)}{row_number + 1}"
        else:
            quantity = pd.to_numeric(element.get("Total_Quantity"), errors="coerce")
            if pd.isna(quantity) or not np.isfinite(quantity) or quantity <= 0:
                raise ValueError(f"Element_Inventory has no positive PLI quantity for {element_id}.")
            quantity_source = "Element_Inventory.Total_Quantity"
        original_quantity = pd.to_numeric(element.get("Inventory_Total_Quantity"), errors="coerce")
        if pd.isna(original_quantity) or not np.isclose(quantity, original_quantity, rtol=0.0, atol=1e-9):
            context["warnings"].append(
                f"{element_id}: active PLI quantity {quantity:.12g} from {quantity_source} "
                f"differs from inventory quantity {_excel_text(element.get('Inventory_Total_Quantity'))}. "
                "The active quantity is used for the element cap and category denominator; "
                "the original inventory quantity is retained separately for review."
            )
        active_quantities.append(float(quantity))
        quantity_sources.append(quantity_source)
    adjusted["Total_Quantity"] = active_quantities
    active_quantity_map = adjusted.set_index("Element_ID")["Total_Quantity"].to_dict()
    inconsistent = [element_id for element_id, quantity in record_quantities.items()
                    if not np.isclose(quantity, active_quantity_map[element_id], rtol=0.0, atol=1e-9)]
    if inconsistent:
        raise ValueError(
            "Active PLI record and denominator quantities disagree for: " + ", ".join(inconsistent)
            + ". Review the explicit quantity sources before aggregation."
        )
    adjusted["PLI_Quantity_Source"] = quantity_sources
    context["sources"]["PLI quantities"] = "Active Calculation_Details quantity dependencies" if calculation_rows else "Element_Inventory.Total_Quantity"
    for column in adjusted.columns:
        if "support_status" in str(column).lower():
            unsupported = adjusted.loc[adjusted[column].apply(_excel_text).str.lower() == "unsupported", "Element_ID"].tolist()
            if unsupported:
                context["warnings"].append(
                    f"Source {column} is Unsupported for: " + ", ".join(unsupported)
                    + ". Reproducing the active workbook calculation does not verify these quantities."
                )
    for column in adjusted.columns:
        if "support_status" in str(column).lower():
            supplied = adjusted.loc[
                adjusted[column].apply(_excel_text).str.lower() == "user provided", "Element_ID"
            ].tolist()
            if supplied:
                context["infos"].append(
                    "User-provided quantities retained for: " + ", ".join(supplied)
                    + ". User confirmation is recorded separately from independent measurement verification."
                )
    if "Measurement_Basis" in adjusted:
        for category, group in adjusted.groupby("Element_Type"):
            units = set(group["Measurement_Basis"].apply(_excel_text)) - {""}
            if len(units) > 1:
                raise ValueError(f"PLI category {category} mixes incompatible measurement units.")
    columns = ["Loss_Record_ID", "Element_ID", "Damage_Extent_%", "Severity_Factor", "Record_Total_Quantity", "Measurement_Basis", "Source_Row", "Input_Table"]
    return pd.DataFrame(records, columns=columns), adjusted


def _finish_upload_review(excel_file, result):
    context = _upload_import_context(excel_file)
    result["Import_Protocol"] = UPLOAD_ASSESSMENT_PROTOCOL
    result["Record_Weight_Policy"] = (
        "Automatic validated workbook record weights"
        if context.get("allow_workbook_record_weights", True)
        else "Explicit counts or exact algebraic cancellation"
    )
    result["Record_Weight_Categories"] = []
    required = (
        ["DI", "PLI", "SI", "FAI"] if result["template_type"] == "Complete Building Assessment"
        else [result["template_type"]] if result["template_type"] in {"DI", "PLI", "SI"}
        else []
    )
    result["Pending_Indices"] = [name for name in required if _upload_optional_number(result.get(name)) is None]
    if "di_elements" in result:
        context["warnings"].extend(_di_review_messages(result["di_elements"], result.get("DI")))
        result["di_categories"] = pd.DataFrame(result["di_elements"].attrs.get("category_results", []))
        record_categories = result["di_elements"].loc[
            result["di_elements"]["DI_Count_Method"].eq("Workbook assessment-record weights"),
            "Element_Type",
        ].drop_duplicates().tolist()
        result["Record_Weight_Categories"] = record_categories
        if record_categories:
            context["infos"].append(
                "DI uses the workbook's assessment-record weights for: "
                + ", ".join(record_categories)
                + ". These declared weights define the assessment-record basis; "
                "physical member counts are neither inferred nor independently verified."
            )
    context["warnings"].extend(_upload_source_qualifications(excel_file))
    if result["template_type"] == "Complete Building Assessment":
        comparison = _compare_saved_excel(excel_file, result["building_info"], result)
        result["Saved_Excel_Comparison"] = comparison
        context["warnings"].extend(comparison.attrs.get("warnings", []))
        context["sources"]["Saved PLI comparison"] = comparison.attrs.get("saved_sources", {}).get("PLI", "Unavailable")
    result["Import_Provenance"] = context["sources"].copy()
    result["Import_Warnings"] = list(dict.fromkeys(context["warnings"]))
    result["Import_Info"] = list(dict.fromkeys(context["infos"]))
    result["Assessment_Status"] = (
        "Pending — input completion required" if result["Pending_Indices"]
        else "Calculated — source notes available" if result["Import_Warnings"]
        else "Calculated — input checks passed"
    )
    result["AI_Ready"] = _upload_ai_ready(result)
    return result


def _prepare_element_inventory(excel_file, system, sheet_name="Element_Inventory", require_quantity=False):
    elements = _read_table(excel_file, sheet_name).copy()

    required_columns = ["Element_ID", "Element_Type"]
    if require_quantity:
        required_columns.append("Total_Quantity")

    missing_columns = [
        column for column in required_columns
        if column not in elements.columns
    ]
    if missing_columns:
        raise ValueError(
            f"{sheet_name} is missing required columns: "
            + ", ".join(missing_columns)
        )

    elements["Element_ID"] = elements["Element_ID"].apply(_excel_text)
    elements["Element_Type"] = elements["Element_Type"].apply(_excel_text)
    elements = elements[elements["Element_ID"] != ""].copy()

    # The generated templates contain an instructional footer in column A.
    # Exclude that footer without masking a genuine incomplete element row.
    footer_note_mask = (
        (elements["Element_Type"] == "")
        & (elements["Element_ID"].str.len() > 30)
    )
    elements = elements[~footer_note_mask].copy()

    incomplete_elements = elements[elements["Element_Type"] == ""]
    if len(incomplete_elements) > 0:
        raise ValueError(
            f"{sheet_name} contains an Element_ID without an Element_Type: "
            + ", ".join(incomplete_elements["Element_ID"].tolist())
        )

    if len(elements) == 0:
        raise ValueError(f"{sheet_name} does not contain any entered physical elements.")

    duplicated_ids = elements.loc[
        elements["Element_ID"].duplicated(keep=False),
        "Element_ID",
    ].tolist()
    if duplicated_ids:
        raise ValueError(
            "Duplicate Element_ID values were found: "
            + ", ".join(sorted(set(duplicated_ids)))
        )

    approved_weights = _upload_ahp_weights(excel_file, system)
    unknown_types = sorted(
        set(elements.loc[
            ~elements["Element_Type"].isin(approved_weights.keys()),
            "Element_Type",
        ].tolist())
    )
    if unknown_types:
        raise ValueError(
            "The following Element_Type values are not valid for the selected structural system: "
            + ", ".join(unknown_types)
        )

    elements["Category_AHP_Weight"] = elements["Element_Type"].map(approved_weights).astype(float)

    elements = _attach_upload_element_counts(
        excel_file, elements, sheet_name,
        allow_workbook_record_weights=_upload_import_context(excel_file).get(
            "allow_workbook_record_weights", True
        ),
    )

    if require_quantity:
        elements["Total_Quantity"] = pd.to_numeric(
            elements["Total_Quantity"],
            errors="coerce",
        )
        invalid_quantity = elements[
            elements["Total_Quantity"].isna()
            | (elements["Total_Quantity"] <= 0)
        ]
        if len(invalid_quantity) > 0:
            raise ValueError(
                "Total_Quantity must be greater than zero for every listed physical element. "
                "Review Element_ID: "
                + ", ".join(invalid_quantity["Element_ID"].tolist())
            )

    return elements


def _di_review_messages(elements, di_value):
    """Report B01 count/damage gaps and uncapped sums without inventing results."""
    messages = list(elements.attrs.get("pending_reasons", []))
    over_limit = elements.loc[elements["Element_DI"] > 100.0]
    if len(over_limit) > 0:
        element_values = ", ".join(
            f"{row['Element_ID']}={float(row['Element_DI']):.6g}"
            for _, row in over_limit.iterrows()
        )
        messages.append(
            "CHECK ELEMENT DI >100: " + element_values
            + ". The uncapped B01 sums are retained. Review overlapping or duplicated damage records."
        )
    numeric_di = _upload_optional_number(di_value)
    if numeric_di is not None and not 0.0 <= numeric_di <= 100.0:
        messages.append(
            f"Building DI ({numeric_di:.6g}) is outside the accepted 0-100 range. "
            "The raw result is retained for review; FAI and Excel-mode AI remain unavailable. No cap is applied."
        )
    return messages


def _extract_di_from_excel(excel_file, info):
    system = _normalize_structural_system(info.get("Structural_System"))
    elements = _prepare_element_inventory(excel_file, system)
    damages = _read_table(excel_file, "Damage_Assessment").copy()

    required = ["Element_ID", "Damage_Extent_%", "Severity_Factor"]
    missing = [column for column in required if column not in damages.columns]
    if missing:
        raise ValueError(
            "Damage_Assessment is missing required columns: "
            + ", ".join(missing)
        )

    candidate_mask = damages[required].notna().any(axis=1)
    damages = damages[candidate_mask].copy()
    damages["Element_ID"] = damages["Element_ID"].apply(_excel_text)

    if len(damages) > 0:
        incomplete = damages[
            (damages["Element_ID"] == "")
            | damages["Damage_Extent_%"].isna()
            | damages["Severity_Factor"].isna()
        ]
        if len(incomplete) > 0:
            raise ValueError(
                "Damage_Assessment contains incomplete damage records. "
                "Each entered row needs Element_ID, Damage_Extent_%, and Severity_Factor."
            )

        unknown_ids = sorted(
            set(damages["Element_ID"]) - set(elements["Element_ID"])
        )
        if unknown_ids:
            raise ValueError(
                "Damage_Assessment references unknown Element_ID values: "
                + ", ".join(unknown_ids)
            )

        damages["Damage_Extent_%"] = pd.to_numeric(
            damages["Damage_Extent_%"],
            errors="coerce",
        )
        damages["Severity_Factor"] = pd.to_numeric(
            damages["Severity_Factor"],
            errors="coerce",
        )

        if damages["Damage_Extent_%"].isna().any() or damages["Severity_Factor"].isna().any():
            raise ValueError("DI damage extent and severity values must be numeric.")

        if ((damages["Damage_Extent_%"] < 0) | (damages["Damage_Extent_%"] > 100)).any():
            raise ValueError("DI Damage_Extent_% must be within 0–100.")

        if not damages["Severity_Factor"].isin([0.25, 0.50, 0.75, 0.90, 1.00]).all():
            raise ValueError("DI Severity_Factor must be one of 0.25, 0.50, 0.75, 0.90, 1.00.")

        damages["Damage_Contribution"] = (
            damages["Damage_Extent_%"]
            * damages["Severity_Factor"]
        )
        # B01 protocol: retain the uncapped sum of all damage records per element.
        element_di_map = damages.groupby("Element_ID")["Damage_Contribution"].sum().to_dict()
    else:
        damages["Damage_Contribution"] = pd.Series(dtype=float)
        element_di_map = {}

    di_value, elements = _aggregate_b01_uploaded_di(elements, element_di_map)
    context = _upload_import_context(excel_file)
    declared_groups = elements.loc[
        elements["Damage_Record_Status"].eq("Declared zero assessment - source-listed group"),
        "Element_ID",
    ].tolist()
    if declared_groups:
        context["sources"]["DI declared-zero groups"] = (
            "Element_Inventory.Element_Count, Source_Element_List, Source_Audit_Note"
        )
        context["infos"].append(
            "DI retains the workbook\'s declared zero-assessment convention for: "
            + ", ".join(declared_groups)
            + ". The listed group counts and explicit zero assignment are used; "
            "this is not an independent field confirmation of sound condition."
        )
    confirmed_elements = elements.loc[
        elements["Damage_Record_Status"].eq("User-provided whole-element no-damage confirmation"),
        "Element_ID",
    ].tolist()
    if confirmed_elements:
        context["sources"]["DI whole-element no-damage confirmation"] = (
            "Element_Inventory.PLI_No_Damage_Confirmation + Condition_Confirmation_Source"
        )
        context["infos"].append(
            "DI uses an explicit user-provided whole-element no-damage confirmation for: "
            + ", ".join(confirmed_elements)
            + ". A PLI-only zero-loss value is not used as a DI observation."
        )

    return di_value, system, elements, damages



def _category_based_pli(elements, quantity_col, loss_col):
    """Physical loss index: quantity-weighted within each category, AHP-weighted across categories."""
    data = elements.copy()
    data[loss_col] = data[[loss_col, quantity_col]].min(axis=1).clip(lower=0.0)
    data["Element_PLI"] = 100.0 * data[loss_col] / data[quantity_col]
    data["Category_Total_Quantity"] = data.groupby("Element_Type")[quantity_col].transform("sum")
    data["Category_Total_Loss"] = data.groupby("Element_Type")[loss_col].transform("sum")
    data["Category_PLR"] = 100.0 * data["Category_Total_Loss"] / data["Category_Total_Quantity"]
    # Weighted_PLI is an element's additive contribution to the numerator,
    # NOT its former element-AHP-weighted loss percentage.
    data["Weighted_PLI"] = (100.0 * data["Category_AHP_Weight"]
                            * data[loss_col] / data["Category_Total_Quantity"])
    categories = data.drop_duplicates("Element_Type")
    total_weight = float(categories["Category_AHP_Weight"].sum())
    if total_weight <= 0:
        raise ValueError("Sum of present category AHP weights must be positive")
    result = float((categories["Category_AHP_Weight"] * categories["Category_PLR"]).sum() / total_weight)
    return result, data, total_weight

def _extract_pli_from_excel(excel_file, info):
    system = _normalize_structural_system(info.get("Structural_System"))
    elements = _prepare_element_inventory(
        excel_file,
        system,
        require_quantity=False,
    )
    losses, elements = _read_active_pli_inputs(excel_file, elements)

    required = ["Element_ID", "Damage_Extent_%", "Severity_Factor"]
    missing = [column for column in required if column not in losses.columns]
    if missing:
        raise ValueError(
            "Physical_Loss is missing required columns: "
            + ", ".join(missing)
        )

    # Only assessment records should enter PLI validation. The shared Excel
    # template may contain audit formulas below the input table (e.g. F59),
    # which must not be interpreted as incomplete damage records.
    if "Loss_Record_ID" not in losses.columns:
        raise ValueError("Physical_Loss is missing required column: Loss_Record_ID.")

    record_id = losses["Loss_Record_ID"].apply(_excel_text)
    element_id = losses["Element_ID"].apply(_excel_text)
    severity = losses["Severity_Factor"].apply(_excel_text)
    identified = record_id.ne("")
    last_record_index = losses.index[identified].max() if identified.any() else None

    # Include incomplete rows between recorded damage entries, even when their
    # ID is missing; also catch entries with an Element_ID or severity beyond
    # the identified range. A lone extent value outside the input area is an
    # audit-cell candidate, not by itself a damage record.
    in_record_region = (
        losses.index <= last_record_index
        if last_record_index is not None
        else pd.Series(False, index=losses.index)
    )
    candidate_mask = (
        identified | element_id.ne("") | severity.ne("")
        | (in_record_region & losses[required].notna().any(axis=1))
    )
    losses = losses[candidate_mask].copy()
    losses["Element_ID"] = losses["Element_ID"].apply(_excel_text)

    quantity_map = elements.set_index("Element_ID")["Total_Quantity"].to_dict()

    if len(losses) > 0:
        incomplete = losses[
            (losses["Element_ID"] == "")
            | losses["Damage_Extent_%"].isna()
            | losses["Severity_Factor"].isna()
        ]
        if len(incomplete) > 0:
            raise ValueError(
                "Physical_Loss contains incomplete records. "
                "Each entered row needs Element_ID, Damage_Extent_%, and Severity_Factor."
            )

        unknown_ids = sorted(
            set(losses["Element_ID"]) - set(elements["Element_ID"])
        )
        if unknown_ids:
            raise ValueError(
                "Physical_Loss references unknown Element_ID values: "
                + ", ".join(unknown_ids)
            )

        losses["Damage_Extent_%"] = pd.to_numeric(
            losses["Damage_Extent_%"],
            errors="coerce",
        )
        losses["Severity_Factor"] = pd.to_numeric(
            losses["Severity_Factor"],
            errors="coerce",
        )

        if losses["Damage_Extent_%"].isna().any() or losses["Severity_Factor"].isna().any():
            raise ValueError("PLI damage extent and severity values must be numeric.")

        if ((losses["Damage_Extent_%"] < 0) | (losses["Damage_Extent_%"] > 100)).any():
            raise ValueError("PLI Damage_Extent_% must be within 0–100.")

        if not losses["Severity_Factor"].isin([0.25, 0.50, 0.75, 0.90, 1.00]).all():
            raise ValueError("PLI Severity_Factor must be one of 0.25, 0.50, 0.75, 0.90, 1.00.")

        losses["Total_Quantity_Recomputed"] = losses["Record_Total_Quantity"].astype(float)
        losses["Physical_Loss_Quantity_Recomputed"] = (
            losses["Total_Quantity_Recomputed"]
            * (losses["Damage_Extent_%"] / 100.0)
            * losses["Severity_Factor"]
        )
        element_loss_map = (
            losses.groupby("Element_ID")["Physical_Loss_Quantity_Recomputed"]
            .sum()
            .to_dict()
        )
    else:
        losses["Physical_Loss_Quantity_Recomputed"] = pd.Series(dtype=float)
        element_loss_map = {}

    elements["Total_Physical_Loss"] = elements["Element_ID"].map(element_loss_map).fillna(0.0)
    pli_value, elements, _ = _category_based_pli(
        elements, "Total_Quantity", "Total_Physical_Loss"
    )

    return pli_value, system, elements, losses


def _extract_tri_from_excel(excel_file, info):
    availability = _excel_text(info.get("Test_Results_Availability"))
    if availability not in {"Available", "Not Available"}:
        raise ValueError(
            "Test_Results_Availability must be set to Available or Not Available."
        )

    system = _normalize_structural_system(info.get("Structural_System"))
    tests = _read_table(excel_file, "Test_Results").copy()

    required = ["Element_ID", "Test_Type", "Test_Value", "Reference_Value"]
    missing = [column for column in required if column not in tests.columns]
    if missing:
        raise ValueError(
            "Test_Results is missing required columns: "
            + ", ".join(missing)
        )

    candidate_mask = tests[required].notna().any(axis=1)
    tests = tests[candidate_mask].copy()
    tests["Element_ID"] = tests["Element_ID"].apply(_excel_text)
    tests["Test_Type"] = tests["Test_Type"].apply(_excel_text)

    if availability == "Not Available":
        if len(tests) > 0:
            raise ValueError(
                "Test results were entered while Test_Results_Availability is set to Not Available."
            )
        return None, 0, "Not Available", system, pd.DataFrame(), pd.DataFrame()

    if len(tests) == 0:
        return None, 0, "Not Available", system, pd.DataFrame(), pd.DataFrame()

    incomplete = tests[
        (tests["Element_ID"] == "")
        | (tests["Test_Type"] == "")
        | tests["Test_Value"].isna()
        | tests["Reference_Value"].isna()
    ]
    if len(incomplete) > 0:
        raise ValueError(
            "Test_Results contains incomplete records. "
            "Each entered row needs Element_ID, Test_Type, Test_Value, and Reference_Value."
        )

    inventory_sheet = (
        "Tested_Element_Inventory"
        if "Tested_Element_Inventory" in excel_file.sheet_names
        else "Element_Inventory"
    )
    elements = _prepare_element_inventory(
        excel_file,
        system,
        sheet_name=inventory_sheet,
        require_quantity=False,
    )

    element_type_map = elements.set_index("Element_ID")["Element_Type"].to_dict()
    approved_element_weights = _upload_ahp_weights(excel_file, system)

    unknown_ids = sorted(set(tests["Element_ID"]) - set(elements["Element_ID"]))
    if unknown_ids:
        raise ValueError(
            "Test_Results references unknown Element_ID values: "
            + ", ".join(unknown_ids)
        )

    unknown_tests = sorted(
        set(tests["Test_Type"]) - set(TRI_UPLOAD_TEST_LIBRARY.keys())
    )
    if unknown_tests:
        raise ValueError(
            "Unknown TRI Test_Type values were found: "
            + ", ".join(unknown_tests)
        )

    normalized_scores = []
    element_weights = []
    test_weights = []
    combined_weights = []
    weighted_scores = []

    for _, row in tests.iterrows():
        test_type = row["Test_Type"]
        config = TRI_UPLOAD_TEST_LIBRARY[test_type]
        test_value = _excel_number(row["Test_Value"], f"{test_type} Test_Value")
        reference_value = _excel_number(row["Reference_Value"], f"{test_type} Reference_Value")

        element_type = element_type_map[row["Element_ID"]]
        element_weight = float(approved_element_weights[element_type])
        test_weight = float(config["Test_Weight"])

        if config["Direction"] == "Benefit":
            if reference_value <= 0 or test_value < 0:
                raise ValueError(
                    f"{test_type}: Benefit normalization requires Reference_Value > 0 and Test_Value >= 0."
                )
            normalized = min(1.0, max(0.0, test_value / reference_value))
        elif test_type == "Half-Cell Potential":
            reference_magnitude = abs(reference_value)
            test_magnitude = abs(test_value)
            if reference_magnitude <= 0:
                raise ValueError(
                    "Half-Cell Potential Reference_Value magnitude must be greater than zero."
                )
            normalized = 1.0 if test_magnitude == 0 else min(1.0, reference_magnitude / test_magnitude)
        else:
            if reference_value <= 0 or test_value < 0:
                raise ValueError(
                    f"{test_type}: Cost normalization requires Reference_Value > 0 and Test_Value >= 0."
                )
            normalized = 1.0 if test_value == 0 else min(1.0, reference_value / test_value)

        combined = element_weight * test_weight
        weighted = normalized * combined

        normalized_scores.append(normalized)
        element_weights.append(element_weight)
        test_weights.append(test_weight)
        combined_weights.append(combined)
        weighted_scores.append(weighted)

    tests["Normalized_Score_0_1_Recomputed"] = normalized_scores
    tests["Normalized_Score_0_100_Recomputed"] = tests["Normalized_Score_0_1_Recomputed"] * 100.0
    tests["Element_Weight_Recomputed"] = element_weights
    tests["Test_Weight_Recomputed"] = test_weights
    tests["Combined_Weight_Recomputed"] = combined_weights
    tests["Weighted_Score_Recomputed"] = weighted_scores

    denominator = float(tests["Combined_Weight_Recomputed"].sum())
    if denominator <= 0:
        raise ValueError("TRI combined-weight sum is zero.")

    tri_value = float(
        tests["Weighted_Score_Recomputed"].sum()
        / denominator
        * 100.0
    )

    element_summary_rows = []
    for element_id, group in tests.groupby("Element_ID"):
        element_summary_rows.append({
            "Element_ID": element_id,
            "Element_TRI": (
                group["Weighted_Score_Recomputed"].sum()
                / group["Combined_Weight_Recomputed"].sum()
                * 100.0
            ),
        })
    element_summary = pd.DataFrame(element_summary_rows)

    return tri_value, 1, "Available", system, tests, element_summary


def _extract_si_from_excel(excel_file, info):
    heritage = _excel_text(info.get("Heritage_Building"))
    if heritage not in {"Yes", "No"}:
        raise ValueError("Heritage_Building must be set to Yes or No.")

    criteria = _read_table(excel_file, "Sustainability_Assessment").copy()
    required = ["Criterion_Code", "Assessment_Status", "Assessment_Score_1_5"]
    missing = [column for column in required if column not in criteria.columns]
    if missing:
        raise ValueError(
            "Sustainability_Assessment is missing required columns: "
            + ", ".join(missing)
        )

    criteria["Criterion_Code"] = criteria["Criterion_Code"].apply(_excel_text)
    criteria = criteria[criteria["Criterion_Code"].isin(SI_UPLOAD_CRITERIA.keys())].copy()

    if set(criteria["Criterion_Code"]) != set(SI_UPLOAD_CRITERIA.keys()):
        raise ValueError("The Sustainability_Assessment sheet must contain all six approved SI criteria.")

    score_map = {1: 0.0, 2: 25.0, 3: 50.0, 4: 75.0, 5: 100.0}
    detail_rows = []
    numerator = 0.0
    denominator = 0.0

    for criterion_code, config in SI_UPLOAD_CRITERIA.items():
        row = criteria.loc[criteria["Criterion_Code"] == criterion_code].iloc[0]

        if criterion_code == "SOC2" and heritage == "No":
            status = "Not Applicable"
        else:
            status = _excel_text(row["Assessment_Status"])
            if criterion_code == "SOC2" and heritage == "Yes" and status == "":
                # Compatibility with the approved template where SOC2 may be formula-driven.
                status = "Applicable"

        if status not in {"Applicable", "Not Applicable"}:
            raise ValueError(
                f"{criterion_code}: Assessment_Status must be Applicable or Not Applicable."
            )

        global_weight = float(config["Global_Weight"])
        raw_score = None
        normalized_score = None

        if status == "Applicable":
            numeric_score = pd.to_numeric(row["Assessment_Score_1_5"], errors="coerce")
            if pd.isna(numeric_score):
                raise ValueError(
                    f"{criterion_code} is Applicable but Assessment_Score_1_5 is missing."
                )
            if (isinstance(row["Assessment_Score_1_5"], (bool, np.bool_))
                    or not np.isfinite(numeric_score)
                    or not float(numeric_score).is_integer()
                    or not 1 <= numeric_score <= 5):
                raise ValueError(
                    f"{criterion_code}: Assessment_Score_1_5 must be a finite integer from 1 to 5."
                )
            numeric_score = int(numeric_score)
            if numeric_score not in score_map:
                raise ValueError(
                    f"{criterion_code}: Assessment_Score_1_5 must be an integer from 1 to 5."
                )

            raw_score = numeric_score
            normalized_score = score_map[numeric_score]
            numerator += normalized_score * global_weight
            denominator += global_weight

        detail_rows.append({
            "Criterion_Code": criterion_code,
            "Dimension": config["Dimension"],
            "Status": status,
            "Raw_Score_1_5": raw_score,
            "Normalized_Score_0_100": normalized_score,
            "Global_Weight": global_weight,
        })

    if denominator <= 0:
        raise ValueError("No SI criterion is marked Applicable.")

    si_value = float(numerator / denominator)
    details = pd.DataFrame(detail_rows)
    details["Renormalized_Weight"] = details.apply(
        lambda row: (
            row["Global_Weight"] / denominator
            if row["Status"] == "Applicable"
            else np.nan
        ),
        axis=1,
    )
    details["Renormalized_Weighted_Score"] = details.apply(
        lambda row: (
            row["Normalized_Score_0_100"] * row["Renormalized_Weight"]
            if row["Status"] == "Applicable"
            else np.nan
        ),
        axis=1,
    )

    return si_value, heritage, denominator, details


def _extract_safety_override(excel_file):
    if "Safety_Override" not in excel_file.sheet_names:
        return 0, [], "Not Activated"

    safety = _read_table(excel_file, "Safety_Override").copy()
    required = ["Code", "Confirmed"]
    missing = [column for column in required if column not in safety.columns]
    if missing:
        raise ValueError(
            "Safety_Override is missing required columns: "
            + ", ".join(missing)
        )

    safety["Code"] = safety["Code"].apply(_excel_text)
    safety["Confirmed"] = safety["Confirmed"].apply(_excel_text)
    safety = safety[safety["Code"].isin(["CF1", "CF2", "CF3"])].copy()

    if set(safety["Code"]) != {"CF1", "CF2", "CF3"}:
        raise ValueError("Safety_Override must contain CF1, CF2, and CF3.")

    invalid = safety[~safety["Confirmed"].isin(["Yes", "No"])]
    if len(invalid) > 0:
        raise ValueError(
            "Safety_Override requires an explicit Yes/No response for CF1, CF2, and CF3."
        )

    confirmed_codes = safety.loc[safety["Confirmed"] == "Yes", "Code"].tolist()
    flag = 1 if confirmed_codes else 0
    status = "Activated" if flag == 1 else "Not Activated"
    return flag, confirmed_codes, status


def _calculate_fai_from_indices(di_value, pli_value, tri_value, tri_flag, si_value):
    if tri_flag not in (0, 1):
        raise ValueError("TRI_Availability_Flag must be 0 or 1.")
    raw_values = {
        "DI": _upload_optional_number(di_value),
        "PLI": _upload_optional_number(pli_value),
        "TRI": _upload_optional_number(tri_value) if tri_flag == 1 else None,
        "SI": _upload_optional_number(si_value),
    }
    weights = FULL_FAI_UPLOAD_WEIGHTS.copy() if tri_flag == 1 else NO_TRI_FAI_UPLOAD_WEIGHTS.copy()
    base_scenario = "Full 4-Index Assessment" if tri_flag == 1 else "TRI Not Available – 3-Index Assessment"
    required = ["DI", "PLI", "SI"] + (["TRI"] if tri_flag == 1 else [])
    missing = [name for name in required if raw_values[name] is None]
    outside = [name for name in required if raw_values[name] is not None and not 0.0 <= raw_values[name] <= 100.0]
    directions = {
        "DI": "Adverse → 100 − DI", "PLI": "Adverse → 100 − PLI",
        "TRI": "Benefit", "SI": "Benefit",
    }
    rows = []
    for name in ["DI", "PLI", "TRI", "SI"]:
        weight = float(weights.get(name, 0.0))
        if weight <= 0:
            continue
        value = raw_values[name]
        converted = None
        if value is not None and 0.0 <= value <= 100.0:
            converted = 100.0 - value if name in {"DI", "PLI"} else value
        rows.append({
            "Index": name, "Index_Value": value, "Direction": directions[name],
            "Converted_Score": converted, "Applied_Weight": weight,
            "FAI_Contribution": None if converted is None else converted * weight,
        })
    details = pd.DataFrame(rows)
    if missing or outside:
        reasons = []
        if missing:
            reasons.append("missing " + ", ".join(missing))
        if outside:
            reasons.append("outside 0–100: " + ", ".join(outside))
        return None, "Not Available", "Pending — " + "; ".join(reasons) + " (" + base_scenario + ")", details
    fai_value = max(0.0, min(100.0, float(sum(row["FAI_Contribution"] for row in rows))))
    return fai_value, get_fai_class(fai_value), base_scenario, details


def _validate_complete_building_info(info):
    required_text_fields = [
        "Building_ID",
        "Building_Name",
        "Building_Function",
        "Structural_System",
    ]
    missing = [
        field for field in required_text_fields
        if _excel_text(info.get(field)) == ""
    ]
    if missing:
        raise ValueError(
            "Complete assessment Building_Info is missing: "
            + ", ".join(missing)
        )

    approved_functions = {
        "Residential",
        "Educational",
        "Service",
        "Governmental",
        "Healthcare",
        "Heritage",
    }
    function = _excel_text(info.get("Building_Function"))
    if function not in approved_functions:
        raise ValueError(
            "Building_Function must be one of the approved application categories."
        )

    _normalize_structural_system(info.get("Structural_System"))

    age = _excel_number(info.get("Building_Age_Years"), "Building_Age_Years")
    floors = _excel_number(info.get("Number_of_Floors"), "Number_of_Floors")

    if age < 1 or age > 150:
        raise ValueError("Building_Age_Years must be within 1–150.")
    if floors < 1 or floors > 4 or abs(floors - round(floors)) > 1e-9:
        raise ValueError("Number_of_Floors must be an integer within 1–4.")


def process_uploaded_assessment_workbook(
    file_bytes, *, allow_workbook_record_weights=True
):
    if not isinstance(allow_workbook_record_weights, (bool, np.bool_)):
        raise ValueError("allow_workbook_record_weights must be True or False.")
    try:
        excel_file = pd.ExcelFile(BytesIO(file_bytes), engine="openpyxl")
    except ImportError as exc:
        raise RuntimeError(
            "Excel upload requires the openpyxl package. Install it with: pip install openpyxl"
        ) from exc
    except Exception as exc:
        raise ValueError("The uploaded file could not be opened as a valid .xlsx workbook.") from exc

    context = _upload_import_context(excel_file)
    context["allow_workbook_record_weights"] = bool(allow_workbook_record_weights)
    context["sources"]["DI weighting policy"] = (
        "Explicit counts first; validated workbook record weights for count-free categories"
        if allow_workbook_record_weights else
        "Explicit counts or exact algebraic cancellation; record-weight fallback disabled"
    )
    sheets = set(excel_file.sheet_names)
    info = _read_building_info(excel_file)

    is_complete = {
        "Element_Inventory",
        "Damage_Assessment",
        "Physical_Loss",
        "Test_Results",
        "Sustainability_Assessment",
        "Safety_Override",
        "Final_Assessment",
        "App_Export",
    }.issubset(sheets)

    if is_complete:
        _validate_complete_building_info(info)
        di_value, di_system, di_elements, di_damage = _extract_di_from_excel(excel_file, info)
        pli_value, pli_system, pli_elements, pli_losses = _extract_pli_from_excel(excel_file, info)
        tri_value, tri_flag, tri_status, tri_system, tri_tests, tri_elements = _extract_tri_from_excel(excel_file, info)
        si_value, heritage, si_weight_sum, si_details = _extract_si_from_excel(excel_file, info)
        cf_flag, confirmed_cf, safety_status = _extract_safety_override(excel_file)
        fai_value, fai_class, fai_scenario, fai_details = _calculate_fai_from_indices(
            di_value,
            pli_value,
            tri_value,
            tri_flag,
            si_value,
        )

        return _finish_upload_review(excel_file, {
            "template_type": "Complete Building Assessment",
            "building_info": info,
            "DI": di_value,
            "PLI": pli_value,
            "TRI": tri_value,
            "TRI_Availability_Flag": tri_flag,
            "TRI_Status": tri_status,
            "SI": si_value,
            "FAI": fai_value,
            "FAI_Condition_Class": fai_class,
            "FAI_Scenario": fai_scenario,
            "Critical_Failure_Flag": cf_flag,
            "Confirmed_Critical_Failures": confirmed_cf,
            "Safety_Override_Status": safety_status,
            "di_system": di_system,
            "di_elements": di_elements,
            "di_damage": di_damage,
            "pli_system": pli_system,
            "pli_elements": pli_elements,
            "pli_losses": pli_losses,
            "tri_system": tri_system,
            "tri_tests": tri_tests,
            "tri_elements": tri_elements,
            "si_heritage": heritage,
            "si_weight_sum": si_weight_sum,
            "si_details": si_details,
            "fai_details": fai_details,
        })

    if "DI_Summary" in sheets and "Damage_Assessment" in sheets:
        di_value, system, elements, damages = _extract_di_from_excel(excel_file, info)
        return _finish_upload_review(excel_file, {
            "template_type": "DI",
            "building_info": info,
            "DI": di_value,
            "di_system": system,
            "di_elements": elements,
            "di_damage": damages,
        })

    if "PLI_Summary" in sheets and "Physical_Loss" in sheets:
        pli_value, system, elements, losses = _extract_pli_from_excel(excel_file, info)
        return _finish_upload_review(excel_file, {
            "template_type": "PLI",
            "building_info": info,
            "PLI": pli_value,
            "pli_system": system,
            "pli_elements": elements,
            "pli_losses": losses,
        })

    if "TRI_Summary" in sheets and "Test_Results" in sheets:
        tri_value, tri_flag, tri_status, system, test_rows, element_rows = _extract_tri_from_excel(excel_file, info)
        return _finish_upload_review(excel_file, {
            "template_type": "TRI",
            "building_info": info,
            "TRI": tri_value,
            "TRI_Availability_Flag": tri_flag,
            "TRI_Status": tri_status,
            "tri_system": system,
            "tri_tests": test_rows,
            "tri_elements": element_rows,
        })

    if "SI_Summary" in sheets and "Sustainability_Assessment" in sheets:
        si_value, heritage, weight_sum, details = _extract_si_from_excel(excel_file, info)
        return _finish_upload_review(excel_file, {
            "template_type": "SI",
            "building_info": info,
            "SI": si_value,
            "si_heritage": heritage,
            "si_weight_sum": weight_sum,
            "si_details": details,
        })

    raise ValueError(
        "The uploaded workbook is not one of the supported assessment templates."
    )


def load_uploaded_result_into_session(result):
    template_type = result["template_type"]
    _clear_upload_derived_results()
    if template_type in {"DI", "Complete Building Assessment"}:
        st.session_state.calculated_di = _upload_optional_number(result.get("DI"))
        st.session_state.di_structural_system_used = result["di_system"]
        st.session_state.di_element_results = result["di_elements"].copy()
        st.session_state.di_damage_results = result["di_damage"].copy()
    if template_type in {"PLI", "Complete Building Assessment"}:
        st.session_state.calculated_pli = _upload_optional_number(result.get("PLI"))
        st.session_state.pli_structural_system_used = result["pli_system"]
        st.session_state.pli_element_results = result["pli_elements"].copy()
        st.session_state.pli_loss_results = result["pli_losses"].copy()
    if template_type in {"TRI", "Complete Building Assessment"}:
        tri_flag = int(result["TRI_Availability_Flag"])
        st.session_state.tri_availability_flag = tri_flag
        st.session_state.tri_status = result["TRI_Status"]
        st.session_state.calculated_tri = _upload_optional_number(result.get("TRI")) if tri_flag == 1 else None
        st.session_state.tri_structural_system_used = result["tri_system"]
        st.session_state.tri_test_results = result["tri_tests"].copy()
        st.session_state.tri_element_results = result["tri_elements"].copy()
    if template_type in {"SI", "Complete Building Assessment"}:
        st.session_state.calculated_si = _upload_optional_number(result.get("SI"))
        st.session_state.si_criteria_results = result["si_details"].copy()
        st.session_state.si_applicable_weight_sum = float(result["si_weight_sum"])
        st.session_state.si_heritage_status = result["si_heritage"]
    if template_type != "Complete Building Assessment":
        return

    fai = _upload_optional_number(result.get("FAI"))
    st.session_state.calculated_fai = fai
    st.session_state.calculated_fai_class = result["FAI_Condition_Class"]
    st.session_state.fai_scenario = result["FAI_Scenario"]
    st.session_state.fai_calculation_results = result["fai_details"].copy()
    info = result["building_info"]
    critical_flag = int(result["Critical_Failure_Flag"])
    final_decision = (
        "Immediate Action Required" if critical_flag == 1
        else "Pending — assessment inputs incomplete" if fai is None
        else "Condition-Based Decision - " + result["FAI_Condition_Class"]
    )

    def summary_number(name):
        value = _upload_optional_number(result.get(name))
        return round(value, 2) if value is not None else "Not Available"

    summary_data = {
        "Result Source": "Uploaded Assessment Template",
        "Assessment Status": result.get("Assessment_Status", "Source review pending"),
        "Pending Indices": ", ".join(result.get("Pending_Indices", [])) or "None",
        "Source Review Notes": " | ".join(result.get("Import_Warnings", [])) or "No additional source warning recorded",
        "Building ID": _excel_text(info.get("Building_ID")),
        "Building Name": _excel_text(info.get("Building_Name")),
        "Building Function": _excel_text(info.get("Building_Function")),
        "Structural System": _excel_text(info.get("Structural_System")),
        "Building Age (Years)": _excel_text(info.get("Building_Age_Years")),
        "Number of Floors": _excel_text(info.get("Number_of_Floors")),
        "DI": summary_number("DI"), "PLI": summary_number("PLI"),
        "TRI Availability": result["TRI_Status"],
        "TRI": summary_number("TRI") if int(result["TRI_Availability_Flag"]) == 1 else "Not Available",
        "SI": summary_number("SI"),
        "Calculated FAI": summary_number("FAI"),
        "AI-Predicted FAI": "Not Available",
        "Calculated FAI (MCDA)": summary_number("FAI"),
        "Building Condition": result["FAI_Condition_Class"],
        "FAI Scenario": result["FAI_Scenario"],
        "Critical Failure Index": critical_flag,
        "Safety Override Status": result["Safety_Override_Status"],
        "Final Decision": final_decision,
    }
    st.session_state.latest_assessment_summary = pd.DataFrame(
        summary_data.items(), columns=["Assessment Item", "Value"]
    )
    st.session_state.latest_calculated_fai = fai
    st.session_state.latest_calculated_fai_class = result["FAI_Condition_Class"]
    st.session_state.latest_predicted_fai = None
    st.session_state.latest_predicted_class = "Not Available"
    st.session_state.latest_final_assessment_building_index = fai
    st.session_state.latest_building_condition = result["FAI_Condition_Class"]
    st.session_state.latest_final_decision = final_decision
    st.session_state.latest_result_source = "Uploaded Assessment Template — " + result.get("Assessment_Status", "Source review pending")
    st.session_state.latest_fai_scenario = result["FAI_Scenario"]
    st.session_state.latest_confirmed_critical_failures = list(result.get("Confirmed_Critical_Failures", []))
    st.session_state["uploaded_complete_assessment"] = result
    # Pending imports are current for reporting but cannot populate AI widgets.
    st.session_state["ai_input_mode"] = "From uploaded Excel"
    st.session_state["ai_excel_input_selected"] = True
    if not _upload_ai_ready(result):
        st.session_state["ai_excel_pending_sync"] = False
        return
    st.session_state["ai_excel_pending_sync"] = True
    st.session_state["ai_building_id"] = _excel_text(info.get("Building_ID"))
    st.session_state["ai_building_name"] = _excel_text(info.get("Building_Name"))
    st.session_state["ai_building_function"] = _excel_text(info.get("Building_Function"))
    st.session_state["ai_structural_system"] = _normalize_structural_system(info.get("Structural_System"))
    st.session_state["ai_building_age"] = int(float(info.get("Building_Age_Years")))
    st.session_state["ai_number_of_floors"] = int(float(info.get("Number_of_Floors")))
    for field, index in (("ai_di", "DI"), ("ai_pli", "PLI"), ("ai_si", "SI")):
        st.session_state[field] = float(result[index])
    available = int(result["TRI_Availability_Flag"]) == 1
    st.session_state["ai_tri_status"] = "Available" if available else "Not Available"
    st.session_state["ai_tri"] = float(result["TRI"]) if available else 70.0
    confirmed = set(result.get("Confirmed_Critical_Failures", []))
    for code in ("CF1", "CF2", "CF3"):
        st.session_state[f"ai_{code.lower()}"] = code in confirmed



