# PDF ASSESSMENT REPORT
# ============================================================

def _assessment_summary_to_dict(summary_df):
    """Convert the two-column Results & Reports dataframe into a plain dict."""
    if summary_df is None or not isinstance(summary_df, pd.DataFrame):
        return {}

    if not {"Assessment Item", "Value"}.issubset(summary_df.columns):
        return {}

    result = {}
    for _, row in summary_df[["Assessment Item", "Value"]].iterrows():
        key = str(row["Assessment Item"]).strip()
        value = row["Value"]
        if key:
            result[key] = value
    return result


def _pdf_safe_text(value):
    """Return escaped text suitable for ReportLab Paragraph objects."""
    if value is None:
        return "Not Available"

    try:
        if pd.isna(value):
            return "Not Available"
    except Exception:
        pass

    text_value = str(value).strip()
    if text_value == "":
        text_value = "Not Available"
    return html.escape(text_value)


def _pdf_number(value, digits=2):
    """Format numeric report values while preserving Not Available."""
    if value is None:
        return "Not Available"
    try:
        if pd.isna(value):
            return "Not Available"
    except Exception:
        pass
    try:
        return f"{float(value):.{digits}f}"
    except Exception:
        return _pdf_safe_text(value)


def _optional_fai_value(value):
    """Return a valid 0-100 FAI value or None when unavailable."""
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass

    if isinstance(value, str):
        cleaned = value.strip()
        if cleaned == "" or cleaned.lower() in {
            "not available", "n/a", "na", "none", "not calculated"
        }:
            return None
        value = cleaned

    try:
        numeric = float(value)
    except Exception:
        return None

    if not np.isfinite(numeric) or numeric < 0 or numeric > 100:
        return None
    return numeric


def calculate_final_assessment_building_index(calculated_fai, ai_predicted_fai):
    """
    Backward-compatible reporting helper.
    The MCDA-calculated FAI remains the assessment reference and is never
    averaged with the AI prediction. The AI value is reported separately.
    """
    calculated = _optional_fai_value(calculated_fai)
    predicted = _optional_fai_value(ai_predicted_fai)

    if calculated is not None:
        return calculated, "Calculated FAI (MCDA); AI prediction reported separately"
    if predicted is not None:
        return predicted, "AI-Predicted FAI only; calculated FAI not available"
    return None, "Not Available"


def build_assessment_pdf(
    summary_df,
    result_source=None,
    fai_scenario=None,
    confirmed_critical_failures=None,
    assessor_name=None,
):
    """
    Build a concise A4 PDF report from the latest completed assessment.
    The report is generated in memory so Streamlit can download it directly.
    """
    if not REPORTLAB_AVAILABLE:
        raise RuntimeError(
            "PDF report generation requires ReportLab. Install it with: pip install reportlab"
        )

    summary = _assessment_summary_to_dict(summary_df)
    if not summary:
        raise ValueError("No completed assessment summary is available for PDF generation.")

    buffer = BytesIO()
    doc = SimpleDocTemplate(
        buffer,
        pagesize=A4,
        rightMargin=16 * mm,
        leftMargin=16 * mm,
        topMargin=14 * mm,
        bottomMargin=17 * mm,
        title="Building Assessment Summary Report",
        author="Smart Assessment Model - University of Basra",
        subject="Existing Building Assessment Summary",
    )

    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "AssessmentReportTitle",
        parent=styles["Title"],
        fontName="Helvetica-Bold",
        fontSize=15,
        leading=18,
        alignment=TA_CENTER,
        textColor=colors.HexColor("#0F4C5C"),
        spaceAfter=5,
    )
    subtitle_style = ParagraphStyle(
        "AssessmentReportSubtitle",
        parent=styles["Normal"],
        fontName="Helvetica-Bold",
        fontSize=9,
        leading=12,
        alignment=TA_CENTER,
        textColor=colors.HexColor("#2A9D8F"),
        spaceAfter=2,
    )
    section_style = ParagraphStyle(
        "AssessmentSection",
        parent=styles["Heading2"],
        fontName="Helvetica-Bold",
        fontSize=11,
        leading=14,
        textColor=colors.HexColor("#0F4C5C"),
        spaceBefore=7,
        spaceAfter=5,
    )
    body_style = ParagraphStyle(
        "AssessmentBody",
        parent=styles["BodyText"],
        fontName="Helvetica",
        fontSize=8.5,
        leading=11,
        alignment=TA_LEFT,
    )
    body_bold_style = ParagraphStyle(
        "AssessmentBodyBold",
        parent=body_style,
        fontName="Helvetica-Bold",
    )
    center_small_style = ParagraphStyle(
        "AssessmentCenterSmall",
        parent=body_style,
        alignment=TA_CENTER,
        fontSize=8,
        textColor=colors.HexColor("#555555"),
    )

    story = []

    # University logo already embedded in the application.
    try:
        logo_bytes = base64.b64decode(COLLEGE_LOGO_B64)
        logo = RLImage(BytesIO(logo_bytes), width=20 * mm, height=20 * mm)
        logo.hAlign = "CENTER"
        story.append(logo)
        story.append(Spacer(1, 2 * mm))
    except Exception:
        pass

    story.append(Paragraph("UNIVERSITY OF BASRA", subtitle_style))
    story.append(Paragraph("COLLEGE OF ENGINEERING - CIVIL ENGINEERING DEPARTMENT", subtitle_style))
    story.append(Spacer(1, 2 * mm))
    story.append(Paragraph("SMART ASSESSMENT MODEL FOR EXISTING BUILDINGS", title_style))
    story.append(Paragraph("IN URBAN AREAS OF BASRA GOVERNORATE", subtitle_style))
    story.append(Paragraph("BUILDING ASSESSMENT SUMMARY REPORT", subtitle_style))
    story.append(Spacer(1, 3 * mm))
    story.append(HRFlowable(width="100%", thickness=0.7, color=colors.HexColor("#91B9B0")))
    story.append(Spacer(1, 3 * mm))

    report_date = datetime.now().strftime("%d %B %Y")
    story.append(
        Table(
            [
                [Paragraph("<b>Report Date</b>", body_style), Paragraph(_pdf_safe_text(report_date), body_style)],
                [Paragraph("<b>Result Source</b>", body_style), Paragraph(_pdf_safe_text(result_source or summary.get("Result Source")), body_style)],
            ],
            colWidths=[44 * mm, 132 * mm],
            style=TableStyle([
                ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#E8F3F0")),
                ("BOX", (0, 0), (-1, -1), 0.5, colors.HexColor("#91B9B0")),
                ("INNERGRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#D9D9D9")),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("LEFTPADDING", (0, 0), (-1, -1), 6),
                ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                ("TOPPADDING", (0, 0), (-1, -1), 4),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
            ]),
        )
    )

    story.append(Paragraph("Building Information", section_style))
    building_rows = [
        ["Building ID", summary.get("Building ID")],
        ["Building Name", summary.get("Building Name")],
        ["Building Function", summary.get("Building Function")],
        ["Structural System", summary.get("Structural System")],
        ["Building Age (Years)", summary.get("Building Age (Years)")],
        ["Number of Floors", summary.get("Number of Floors")],
    ]
    building_table_data = [
        [Paragraph("<b>Field</b>", body_style), Paragraph("<b>Value</b>", body_style)]
    ] + [
        [Paragraph(f"<b>{_pdf_safe_text(label)}</b>", body_style), Paragraph(_pdf_safe_text(value), body_style)]
        for label, value in building_rows
    ]
    story.append(
        Table(
            building_table_data,
            colWidths=[52 * mm, 124 * mm],
            repeatRows=1,
            style=TableStyle([
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#0F4C5C")),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                ("BACKGROUND", (0, 1), (0, -1), colors.HexColor("#F8F5EE")),
                ("BOX", (0, 0), (-1, -1), 0.5, colors.HexColor("#91B9B0")),
                ("INNERGRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#D9D9D9")),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("LEFTPADDING", (0, 0), (-1, -1), 6),
                ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                ("TOPPADDING", (0, 0), (-1, -1), 4),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
            ]),
        )
    )

    if summary.get("Assessment Status"):
        story.append(Paragraph(
            "<b>Assessment status:</b> " + _pdf_safe_text(summary.get("Assessment Status")),
            body_style,
        ))
        story.append(Paragraph(
            "<b>Pending indices:</b> " + _pdf_safe_text(summary.get("Pending Indices", "None")),
            body_style,
        ))
        if summary.get("Source Review Notes"):
            story.append(Paragraph(
                "<b>Source review:</b> " + _pdf_safe_text(summary.get("Source Review Notes")),
                body_style,
            ))
        story.append(Spacer(1, 3 * mm))
    story.append(Paragraph("Assessment Levels", section_style))
    calculated_fai_value = summary.get("Calculated FAI", summary.get("FAI"))
    predicted_fai_value = summary.get("AI-Predicted FAI", summary.get("Predicted FAI"))
    index_rows = [
        ["Damage Level (DI)", _pdf_number(summary.get("DI"))],
        ["Physical Loss Level (PLI)", _pdf_number(summary.get("PLI"))],
        ["Test Result Level (TRI)", _pdf_number(summary.get("TRI"))],
        ["Sustainability Level (SI)", _pdf_number(summary.get("SI"))],
        ["Calculated FAI (MCDA)", _pdf_number(calculated_fai_value)],
        ["AI-Predicted FAI (Random Forest)", _pdf_number(predicted_fai_value)],
    ]
    index_table_data = [
        [Paragraph("<b>Level</b>", body_style), Paragraph("<b>Value</b>", body_style)]
    ] + [
        [Paragraph(_pdf_safe_text(label), body_style), Paragraph(_pdf_safe_text(value), body_style)]
        for label, value in index_rows
    ]
    story.append(
        Table(
            index_table_data,
            colWidths=[116 * mm, 60 * mm],
            repeatRows=1,
            style=TableStyle([
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#0F4C5C")),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                ("ALIGN", (1, 1), (1, -1), "CENTER"),
                ("BOX", (0, 0), (-1, -1), 0.5, colors.HexColor("#91B9B0")),
                ("INNERGRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#D9D9D9")),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("LEFTPADDING", (0, 0), (-1, -1), 6),
                ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                ("TOPPADDING", (0, 0), (-1, -1), 4),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
            ]),
        )
    )

    calculated_fai_numeric = _optional_fai_value(calculated_fai_value)
    predicted_fai_numeric = _optional_fai_value(predicted_fai_value)
    calculated_condition = (
        get_fai_class(calculated_fai_numeric)
        if calculated_fai_numeric is not None
        else "Not Available"
    )
    predicted_condition = (
        get_fai_class(predicted_fai_numeric)
        if predicted_fai_numeric is not None
        else "Not Available"
    )
    critical_failure_index = summary.get(
        "Critical Failure Index",
        summary.get("Critical Failure Flag"),
    )

    story.append(Paragraph("Final Assessment", section_style))
    final_rows = [
        ["CALCULATED FAI CONDITION", calculated_condition],
        ["AI-PREDICTED FAI CONDITION", predicted_condition],
        ["CRITICAL FAILURE INDEX", critical_failure_index],
        ["SAFETY OVERRIDE STATUS", summary.get("Safety Override Status")],
        ["FINAL DECISION", summary.get("Final Decision")],
    ]
    final_table_data = []
    for idx, (label, value) in enumerate(final_rows):
        if idx == 0:
            label_paragraph = Paragraph(
                f'<font color="#FFFFFF"><b>{_pdf_safe_text(label)}</b></font>',
                body_style,
            )
            value_paragraph = Paragraph(
                f'<font color="#FFFFFF"><b>{_pdf_safe_text(value)}</b></font>',
                body_style,
            )
        else:
            label_paragraph = Paragraph(f"<b>{_pdf_safe_text(label)}</b>", body_style)
            value_paragraph = Paragraph(_pdf_safe_text(value), body_style)
        final_table_data.append([label_paragraph, value_paragraph])
    final_table = Table(
        final_table_data,
        colWidths=[88 * mm, 88 * mm],
        style=TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#0F4C5C")),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
            ("BACKGROUND", (0, 1), (0, -1), colors.HexColor("#E8F3F0")),
            ("BOX", (0, 0), (-1, -1), 0.6, colors.HexColor("#91B9B0")),
            ("INNERGRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#D9D9D9")),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("ALIGN", (1, 0), (1, -1), "CENTER"),
            ("LEFTPADDING", (0, 0), (-1, -1), 6),
            ("RIGHTPADDING", (0, 0), (-1, -1), 6),
            ("TOPPADDING", (0, 0), (-1, -1), 5),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
        ]),
    )
    story.append(final_table)
    story.append(Spacer(1, 2 * mm))
    story.append(
        Paragraph(
            "<b>Reporting rule:</b> The MCDA-calculated FAI and the AI-predicted FAI "
            "are reported independently. No arithmetic mean or fused FAI is calculated.",
            center_small_style,
        )
    )

    confirmed_critical_failures = confirmed_critical_failures or []
    if confirmed_critical_failures:
        story.append(Spacer(1, 3 * mm))
        story.append(
            Table(
                [[Paragraph(
                    "<b>Confirmed Critical Failure Codes:</b> "
                    + _pdf_safe_text(", ".join(confirmed_critical_failures)),
                    body_style,
                )]],
                colWidths=[176 * mm],
                style=TableStyle([
                    ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#FCE8E6")),
                    ("BOX", (0, 0), (-1, -1), 0.6, colors.HexColor("#C00000")),
                    ("LEFTPADDING", (0, 0), (-1, -1), 7),
                    ("RIGHTPADDING", (0, 0), (-1, -1), 7),
                    ("TOPPADDING", (0, 0), (-1, -1), 6),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
                ]),
            )
        )

    story.append(Spacer(1, 2 * mm))
    assessor_display = (str(assessor_name).strip() if assessor_name else "")
    if not assessor_display:
        assessor_display = "____________________________"

    # Assessor and signature are drawn in the lower-right page area instead of
    # being part of the flowing story. This prevents the signature line from
    # being pushed onto a second page when the report nearly fills page 1.

    def _draw_footer(canvas, document):
        canvas.saveState()
        page_width, _ = A4

        # Assessor block - lower right, above the footer rule.
        # The assessment report is intentionally designed as a concise one-page
        # summary, so this keeps the assessor name and signature together.
        if document.page == 1:
            canvas.setFillColor(colors.HexColor("#111111"))
            canvas.setFont("Helvetica-Bold", 8.5)
            canvas.drawRightString(
                page_width - 16 * mm,
                23.0 * mm,
                "ASSESSOR: " + assessor_display,
            )
            canvas.drawRightString(
                page_width - 16 * mm,
                17.5 * mm,
                "SIGNATURE: ____________________________",
            )

        canvas.setStrokeColor(colors.HexColor("#D9D9D9"))
        canvas.setLineWidth(0.4)
        canvas.line(16 * mm, 12 * mm, page_width - 16 * mm, 12 * mm)
        canvas.setFillColor(colors.HexColor("#666666"))
        canvas.setFont("Helvetica", 7)
        canvas.drawString(16 * mm, 7.5 * mm, "Smart Assessment Model | University of Basra")
        canvas.drawRightString(page_width - 16 * mm, 7.5 * mm, f"Page {document.page}")
        canvas.restoreState()

    doc.build(story, onFirstPage=_draw_footer, onLaterPages=_draw_footer)
    buffer.seek(0)
    return buffer.getvalue()


def _assessment_pdf_filename(summary_df):
    summary = _assessment_summary_to_dict(summary_df)
    building_id = str(summary.get("Building ID") or "Building").strip()
    safe_id = "".join(ch if ch.isalnum() or ch in {"-", "_"} else "_" for ch in building_id)
    report_date = datetime.now().strftime("%Y-%m-%d")
    return f"Assessment_Report_{safe_id}_{report_date}.pdf"

